class MemoryCheckpointPreflightError(ValueError):
    """A checkpoint rejection known to occur before the first durable write."""

    def __init__(self, message: str, *, retry_allowed: bool) -> None:
        super().__init__(message)
        self.retry_allowed = retry_allowed

