def _is_route_transition_projection(channel: Any, record: Any) -> bool:
    state = record.get('state') if isinstance(record, dict) else None
    return bool(channel == 'branch_states' and isinstance(state, dict) and (state.get('schema_version') == _ROUTE_TRANSITION_STATE_SCHEMA))

def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()

def _sanitize_problem_component(raw: str) -> str:
    cleaned = re.sub('\\s+', '_', raw.strip())
    cleaned = re.sub('[^A-Za-z0-9._-]', '_', cleaned)
    cleaned = re.sub('_+', '_', cleaned).strip('._')
    return cleaned

def sanitize_problem_id(raw: str) -> str:
    """Return a safe problem id while preserving relative path components."""
    normalized = raw.strip().replace('\\', '/')
    parts: List[str] = []
    for part in normalized.split('/'):
        stripped = part.strip()
        if stripped in {'', '.'}:
            continue
        if stripped == '..':
            raise ValueError("problem_id must not contain '..' path components")
        cleaned = _sanitize_problem_component(stripped)
        if cleaned:
            parts.append(cleaned)
    return '/'.join(parts) or 'problem'

_VERIFIED_PROBLEM_COMPONENT_RE = re.compile('^[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9-])?$')

def validate_verified_problem_id(raw: str) -> str:
    """Validate a publication id without lossy normalization."""
    if not isinstance(raw, str) or not raw or raw != raw.strip() or ('\\' in raw):
        raise ValueError('problem_id must be a non-empty normalized relative path')
    parts = raw.split('/')
    if any((part in {'', '.', '..'} for part in parts)):
        raise ValueError("problem_id must not contain empty, '.', or '..' path components")
    if any((_VERIFIED_PROBLEM_COMPONENT_RE.fullmatch(part) is None for part in parts)):
        raise ValueError("problem_id components must use ASCII letters, digits, '.', '_', or '-' and must begin with an alphanumeric character and end with an alphanumeric character or '-'")
    return raw

def _memory_root_path() -> Path:
    root = Path(os.path.abspath(os.fspath(MEMORY_ROOT)))
    if root == Path(root.anchor):
        raise ValueError('memory root must not be a filesystem root')
    return root

def _problem_dir(problem_id: str) -> Path:
    sanitized_problem_id = sanitize_problem_id(problem_id)
    return _memory_root_path().joinpath(*sanitized_problem_id.split('/'))

def _channel_path(problem_id: str, channel: str) -> Path:
    if channel not in CHANNEL_FILES:
        allowed = ', '.join(sorted(CHANNEL_FILES))
        raise ValueError(f"Unknown channel '{channel}'. Allowed channels: {allowed}")
    return _problem_dir(problem_id) / CHANNEL_FILES[channel]

def _batch_checkpoint_dir(problem_id: str) -> Path:
    return _problem_dir(problem_id) / '.phase_checkpoints'

def _batch_commit_path(checkpoint_path: Path) -> Path:
    if not checkpoint_path.name.endswith('.json'):
        raise ValueError('memory batch checkpoint path is invalid')
    return checkpoint_path.with_name(f".{checkpoint_path.name.removesuffix('.json')}.commit")

def _strict_json_loads(raw: str, *, label: str) -> Any:

    def reject_constant(value: str) -> None:
        raise ValueError(f'{label} contains non-finite JSON constant {value}')

    def reject_duplicate_keys(pairs: List[tuple[str, Any]]) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f'{label} contains duplicate JSON key {key!r}')
            result[key] = value
        return result
    try:
        return json.loads(raw, object_pairs_hook=reject_duplicate_keys, parse_constant=reject_constant)
    except (json.JSONDecodeError, UnicodeError, ValueError) as exc:
        raise ValueError(f'{label} is not valid strict JSON: {exc}') from exc

def _memory_path_parts(path: Path) -> tuple[str, ...]:
    root = _memory_root_path()
    target = Path(os.path.abspath(os.fspath(path)))
    try:
        relative = target.relative_to(root)
    except ValueError as exc:
        raise ValueError('memory path resolves outside memory root') from exc
    parts = relative.parts
    if any((part in {'', '.', '..'} or '/' in part or '\x00' in part for part in parts)):
        raise ValueError('memory path contains an invalid component')
    return parts

def _directory_open_flags() -> int:
    return os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, 'O_CLOEXEC', 0)

def _file_open_flags(flags: int) -> int:
    return flags | os.O_NOFOLLOW | getattr(os, 'O_CLOEXEC', 0)

def _same_inode(left: os.stat_result, right: os.stat_result) -> bool:
    return left.st_dev == right.st_dev and left.st_ino == right.st_ino

def _validate_directory_metadata(metadata: os.stat_result, *, label: str, require_owner: bool) -> None:
    if not stat.S_ISDIR(metadata.st_mode) or metadata.st_nlink < 1:
        raise ValueError(f'{label} is not a durable directory')
    if require_owner:
        if metadata.st_uid != os.geteuid():
            raise ValueError(f'{label} is not owned by the MCP process')
        if metadata.st_mode & 18:
            raise ValueError(f'{label} is writable by group or other users')

def _validate_regular_metadata(metadata: os.stat_result, *, label: str, expected_nlink: int) -> None:
    if not stat.S_ISREG(metadata.st_mode):
        raise ValueError(f'{label} is not a regular file')
    if metadata.st_uid != os.geteuid():
        raise ValueError(f'{label} is not owned by the MCP process')
    if metadata.st_nlink != expected_nlink:
        raise ValueError(f'{label} has an unsafe hard-link count')
    if metadata.st_mode & 18:
        raise ValueError(f'{label} is writable by group or other users')

def _fsync_directory_fd(descriptor: int, path: Path) -> None:
    del path
    os.fsync(descriptor)

def _open_absolute_directory_nofollow(path: Path) -> int:
    absolute = Path(os.path.abspath(os.fspath(path)))
    descriptor = os.open(absolute.anchor, _directory_open_flags())
    current = Path(absolute.anchor)
    try:
        for component in absolute.parts[1:]:
            label = f'memory ancestor {current / component}'
            before = os.stat(component, dir_fd=descriptor, follow_symlinks=False)
            _validate_directory_metadata(before, label=label, require_owner=False)
            child = os.open(component, _directory_open_flags(), dir_fd=descriptor)
            try:
                opened = os.fstat(child)
                after = os.stat(component, dir_fd=descriptor, follow_symlinks=False)
                _validate_directory_metadata(opened, label=label, require_owner=False)
                if not _same_inode(before, opened) or not _same_inode(opened, after):
                    raise ValueError(f'{label} changed while it was opened')
            except BaseException:
                os.close(child)
                raise
            os.close(descriptor)
            descriptor = child
            current /= component
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise

def _open_child_directory_at(parent_descriptor: int, parent_path: Path, name: str, *, create: bool) -> int:
    if name in {'', '.', '..'} or '/' in name or '\x00' in name:
        raise ValueError('memory directory has an invalid component')
    child_path = parent_path / name
    if create:
        try:
            os.mkdir(name, 448, dir_fd=parent_descriptor)
        except FileExistsError:
            pass
        _fsync_directory_fd(parent_descriptor, parent_path)
    before = os.stat(name, dir_fd=parent_descriptor, follow_symlinks=False)
    _validate_directory_metadata(before, label=f'memory directory {child_path}', require_owner=True)
    child = os.open(name, _directory_open_flags(), dir_fd=parent_descriptor)
    try:
        opened = os.fstat(child)
        after = os.stat(name, dir_fd=parent_descriptor, follow_symlinks=False)
        _validate_directory_metadata(opened, label=f'memory directory {child_path}', require_owner=True)
        if not _same_inode(before, opened) or not _same_inode(opened, after):
            raise ValueError(f'memory directory {child_path} changed while opened')
    except BaseException:
        os.close(child)
        raise
    return child

def _open_memory_root(*, create: bool) -> int:
    root = _memory_root_path()
    parent_path = root.parent.resolve(strict=True)
    parent = _open_absolute_directory_nofollow(parent_path)
    try:
        _validate_directory_metadata(os.fstat(parent), label=f'memory root parent {parent_path}', require_owner=False)
        return _open_child_directory_at(parent, parent_path, root.name, create=create)
    finally:
        os.close(parent)

def _open_memory_directory(path: Path, *, create: bool) -> int:
    parts = _memory_path_parts(path)
    descriptor = _open_memory_root(create=create)
    current = _memory_root_path()
    try:
        for component in parts:
            child = _open_child_directory_at(descriptor, current, component, create=create)
            os.close(descriptor)
            descriptor = child
            current /= component
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise

def _open_memory_parent(path: Path, *, create: bool) -> tuple[int, str]:
    parts = _memory_path_parts(path)
    if not parts:
        raise ValueError('memory file path must be below memory root')
    parent = _memory_root_path().joinpath(*parts[:-1])
    return (_open_memory_directory(parent, create=create), parts[-1])

def _ensure_memory_directory_durable(path: Path) -> None:
    """Create a fenced memory directory and durably record every component."""
    descriptor = _open_memory_directory(path, create=True)
    os.close(descriptor)

def _verify_open_regular_at(parent_descriptor: int, name: str, descriptor: int, *, label: str, expected_nlink: int=1) -> os.stat_result:
    opened = os.fstat(descriptor)
    entry = os.stat(name, dir_fd=parent_descriptor, follow_symlinks=False)
    _validate_regular_metadata(opened, label=label, expected_nlink=expected_nlink)
    _validate_regular_metadata(entry, label=label, expected_nlink=expected_nlink)
    if not _same_inode(opened, entry):
        raise ValueError(f'{label} changed after it was opened')
    return opened

def _verify_open_regular_allowed_nlinks(parent_descriptor: int, name: str, descriptor: int, *, label: str, allowed_nlinks: frozenset[int]) -> os.stat_result:
    opened = os.fstat(descriptor)
    entry = os.stat(name, dir_fd=parent_descriptor, follow_symlinks=False)
    if opened.st_nlink not in allowed_nlinks or entry.st_nlink not in allowed_nlinks:
        raise ValueError(f'{label} has an unsafe hard-link count')
    _validate_regular_metadata(opened, label=label, expected_nlink=opened.st_nlink)
    _validate_regular_metadata(entry, label=label, expected_nlink=entry.st_nlink)
    if not _same_inode(opened, entry):
        raise ValueError(f'{label} changed after it was opened')
    return opened

def _open_existing_regular_at(parent_descriptor: int, name: str, flags: int, *, label: str) -> int:
    before = os.stat(name, dir_fd=parent_descriptor, follow_symlinks=False)
    _validate_regular_metadata(before, label=label, expected_nlink=1)
    descriptor = os.open(name, _file_open_flags(flags), dir_fd=parent_descriptor)
    try:
        opened = _verify_open_regular_at(parent_descriptor, name, descriptor, label=label)
        if not _same_inode(before, opened):
            raise ValueError(f'{label} changed while it was opened')
    except BaseException:
        os.close(descriptor)
        raise
    return descriptor

def _open_existing_regular_allowed_nlinks(parent_descriptor: int, name: str, flags: int, *, label: str, allowed_nlinks: frozenset[int]) -> int:
    before = os.stat(name, dir_fd=parent_descriptor, follow_symlinks=False)
    if before.st_nlink not in allowed_nlinks:
        raise ValueError(f'{label} has an unsafe hard-link count')
    _validate_regular_metadata(before, label=label, expected_nlink=before.st_nlink)
    descriptor = os.open(name, _file_open_flags(flags), dir_fd=parent_descriptor)
    try:
        opened = _verify_open_regular_allowed_nlinks(parent_descriptor, name, descriptor, label=label, allowed_nlinks=allowed_nlinks)
        if not _same_inode(before, opened):
            raise ValueError(f'{label} changed while it was opened')
    except BaseException:
        os.close(descriptor)
        raise
    return descriptor

def _open_new_regular_at(parent_descriptor: int, name: str, flags: int, *, label: str) -> int:
    descriptor = os.open(name, _file_open_flags(flags | os.O_CREAT | os.O_EXCL), 384, dir_fd=parent_descriptor)
    try:
        _verify_open_regular_at(parent_descriptor, name, descriptor, label=label)
    except BaseException:
        try:
            entry = os.stat(name, dir_fd=parent_descriptor, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            if _same_inode(entry, os.fstat(descriptor)):
                os.unlink(name, dir_fd=parent_descriptor)
                _fsync_directory_fd(parent_descriptor, Path('.'))
        os.close(descriptor)
        raise
    return descriptor

def _write_all(descriptor: int, encoded: bytes) -> None:
    offset = 0
    while offset < len(encoded):
        written = os.write(descriptor, encoded[offset:])
        if written <= 0:
            raise OSError('short write while persisting memory')
        offset += written

def _read_memory_bytes(path: Path, *, max_bytes: int | None=None, allow_missing: bool=False) -> bytes | None:
    try:
        parent, name = _open_memory_parent(path, create=False)
    except FileNotFoundError:
        if allow_missing:
            return None
        raise
    try:
        try:
            descriptor = _open_existing_regular_at(parent, name, os.O_RDONLY, label=f'memory file {path}')
        except FileNotFoundError:
            if allow_missing:
                return None
            raise
        try:
            chunks: list[bytes] = []
            total = 0
            while True:
                chunk = os.read(descriptor, 65536)
                if not chunk:
                    break
                total += len(chunk)
                if max_bytes is not None and total > max_bytes:
                    raise ValueError(f'memory file exceeds its size limit: {path}')
                chunks.append(chunk)
            _verify_open_regular_at(parent, name, descriptor, label=f'memory file {path}')
            return b''.join(chunks)
        finally:
            os.close(descriptor)
    finally:
        os.close(parent)

def _iter_jsonl(path: Path) -> Iterable[Dict[str, Any]]:
    try:
        parent, name = _open_memory_parent(path, create=False)
    except FileNotFoundError:
        return
    try:
        try:
            descriptor = _open_existing_regular_at(parent, name, os.O_RDONLY, label=f'memory channel {path}')
        except FileNotFoundError:
            return
        try:
            fcntl.flock(descriptor, fcntl.LOCK_SH)
            with os.fdopen(descriptor, 'r', encoding='utf-8', closefd=False) as handle:
                for line_number, line in enumerate(handle, start=1):
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        payload = json.loads(line)
                    except json.JSONDecodeError as exc:
                        raise ValueError(f'memory channel {path} contains invalid JSONL at line {line_number}') from exc
                    if not isinstance(payload, dict):
                        raise ValueError(f'memory channel {path} contains a non-object JSONL record at line {line_number}')
                    yield payload
            _verify_open_regular_at(parent, name, descriptor, label=f'memory channel {path}')
        finally:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            except OSError:
                pass
            os.close(descriptor)
    finally:
        os.close(parent)

def _append_jsonl(path: Path, payload: Dict[str, Any]) -> None:
    encoded = (json.dumps(payload, ensure_ascii=False) + '\n').encode('utf-8')
    parent, name = _open_memory_parent(path, create=False)
    try:
        descriptor = _open_existing_regular_at(parent, name, os.O_WRONLY | os.O_APPEND, label=f'memory channel {path}')
        try:
            fcntl.flock(descriptor, fcntl.LOCK_EX)
            _verify_open_regular_at(parent, name, descriptor, label=f'memory channel {path}')
            _write_all(descriptor, encoded)
            os.fsync(descriptor)
            _verify_open_regular_at(parent, name, descriptor, label=f'memory channel {path}')
        finally:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            finally:
                os.close(descriptor)
    finally:
        os.close(parent)

def _unlink_temporary_durable_at(parent_descriptor: int, parent_path: Path, name: str, descriptor: int | None) -> None:
    try:
        entry = os.stat(name, dir_fd=parent_descriptor, follow_symlinks=False)
    except FileNotFoundError:
        return
    _validate_regular_metadata(entry, label=f'memory temporary {parent_path / name}', expected_nlink=entry.st_nlink)
    if entry.st_nlink not in {1, 2}:
        raise ValueError('memory temporary has an unsafe hard-link count')
    if descriptor is not None and (not _same_inode(entry, os.fstat(descriptor))):
        raise ValueError('memory temporary changed before cleanup')
    os.unlink(name, dir_fd=parent_descriptor)
    _fsync_directory_fd(parent_descriptor, parent_path)

def _write_atomic_json_replace(path: Path, payload: Dict[str, Any]) -> None:
    """Atomically replace fenced mutable JSON without exposing truncation."""
    encoded = (json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + '\n').encode('utf-8')
    parent, name = _open_memory_parent(path, create=False)
    temporary_name = f'.{name}.{uuid.uuid4().hex}.tmp'
    descriptor: int | None = None
    try:
        descriptor = _open_new_regular_at(parent, temporary_name, os.O_WRONLY, label=f'memory metadata temporary {path.parent / temporary_name}')
        _write_all(descriptor, encoded)
        os.fsync(descriptor)
        _verify_open_regular_at(parent, temporary_name, descriptor, label=f'memory metadata temporary {path.parent / temporary_name}')
        try:
            existing = os.stat(name, dir_fd=parent, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            _validate_regular_metadata(existing, label=f'memory metadata {path}', expected_nlink=1)
        os.replace(temporary_name, name, src_dir_fd=parent, dst_dir_fd=parent)
        _verify_open_regular_at(parent, name, descriptor, label=f'memory metadata {path}')
        _fsync_directory_fd(parent, path.parent)
    finally:
        try:
            if descriptor is not None:
                _unlink_temporary_durable_at(parent, path.parent, temporary_name, descriptor)
        finally:
            if descriptor is not None:
                os.close(descriptor)
            os.close(parent)

def _open_durable_lock_file(path: Path) -> int:
    parent, name = _open_memory_parent(path, create=False)
    try:
        try:
            descriptor = _open_new_regular_at(parent, name, os.O_RDWR, label=f'memory lock {path}')
        except FileExistsError:
            descriptor = _open_existing_regular_at(parent, name, os.O_RDWR, label=f'memory lock {path}')
            created = False
        else:
            created = True
        try:
            if created:
                os.fsync(descriptor)
            _verify_open_regular_at(parent, name, descriptor, label=f'memory lock {path}')
            _fsync_directory_fd(parent, path.parent)
        except BaseException:
            os.close(descriptor)
            raise
        return descriptor
    finally:
        os.close(parent)

def _verify_open_memory_file(path: Path, descriptor: int, *, label: str) -> None:
    parent, name = _open_memory_parent(path, create=False)
    try:
        _verify_open_regular_at(parent, name, descriptor, label=label)
    finally:
        os.close(parent)

def _ensure_empty_file_durable(path: Path) -> None:
    parent, name = _open_memory_parent(path, create=False)
    try:
        try:
            descriptor = _open_new_regular_at(parent, name, os.O_WRONLY, label=f'memory channel {path}')
        except FileExistsError:
            descriptor = _open_existing_regular_at(parent, name, os.O_RDONLY, label=f'memory channel {path}')
            created = False
        else:
            created = True
        try:
            if created:
                os.fsync(descriptor)
            _verify_open_regular_at(parent, name, descriptor, label=f'memory channel {path}')
            _fsync_directory_fd(parent, path.parent)
        finally:
            os.close(descriptor)
    finally:
        os.close(parent)

def _recover_checkpoint_orphan_at(parent_descriptor: int, parent_path: Path, name: str, descriptor: int, current_temporary_name: str | None) -> bool:
    """Recover one SIGKILL cut between checkpoint fsync and temp unlink.

    The caller holds an exclusive flock on ``descriptor``.  Recovery is
    deliberately narrower than general hard-link cleanup: the final and the
    one constrained same-inode temp entry must be the only two links to the
    checkpoint inode. Different-inode stale temps are preserved. The caller
    must fully authenticate the checkpoint payload before invoking recovery.
    """
    final_metadata = _verify_open_regular_allowed_nlinks(parent_descriptor, name, descriptor, label=f'memory checkpoint {parent_path / name}', allowed_nlinks=frozenset({1, 2}))
    if final_metadata.st_nlink == 1:
        return False
    temporary_pattern = re.compile(f'^\\.{re.escape(name)}\\.[0-9a-f]{{32}}\\.tmp$')
    same_inode_candidates: List[str] = []
    for candidate in sorted(os.listdir(parent_descriptor)):
        if candidate == current_temporary_name or not temporary_pattern.fullmatch(candidate):
            continue
        try:
            candidate_metadata = os.stat(candidate, dir_fd=parent_descriptor, follow_symlinks=False)
        except FileNotFoundError:
            continue
        if not _same_inode(final_metadata, candidate_metadata):
            continue
        temporary = _open_existing_regular_allowed_nlinks(parent_descriptor, candidate, os.O_RDONLY, label=f'memory checkpoint orphan {parent_path / candidate}', allowed_nlinks=frozenset({2}))
        try:
            if not _same_inode(final_metadata, os.fstat(temporary)):
                raise ValueError('memory checkpoint orphan changed while opened')
        finally:
            os.close(temporary)
        same_inode_candidates.append(candidate)
    if len(same_inode_candidates) != 1:
        raise ValueError('memory checkpoint has no unique same-inode orphan')
    temporary_name = same_inode_candidates[0]
    _unlink_temporary_durable_at(parent_descriptor, parent_path, temporary_name, descriptor)
    _verify_open_regular_at(parent_descriptor, name, descriptor, label=f'memory checkpoint {parent_path / name}')
    return True

def _publish_atomic_json_once(path: Path, payload: Dict[str, Any], *, problem_id: str, expected_normalized_items: List[Dict[str, Any]]) -> bool:
    """Durably publish one immutable fenced JSON value without replacement."""
    encoded = (json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode('utf-8')
    if len(encoded) > MAX_MEMORY_BATCH_FILE_BYTES:
        raise ValueError('encoded batch checkpoint exceeds its file-size limit')
    _ensure_memory_directory_durable(path.parent)
    parent, name = _open_memory_parent(path, create=False)
    temporary_name = f'.{name}.{uuid.uuid4().hex}.tmp'
    descriptor: int | None = None
    published = False
    temporary_locked = False
    try:
        descriptor = _open_new_regular_at(parent, temporary_name, os.O_WRONLY, label=f'memory checkpoint temporary {path.parent / temporary_name}')
        fcntl.flock(descriptor, fcntl.LOCK_EX)
        temporary_locked = True
        _write_all(descriptor, encoded)
        os.fsync(descriptor)
        _verify_open_regular_at(parent, temporary_name, descriptor, label=f'memory checkpoint temporary {path.parent / temporary_name}')
        try:
            os.link(temporary_name, name, src_dir_fd=parent, dst_dir_fd=parent, follow_symlinks=False)
        except FileExistsError:
            winner = _open_existing_regular_allowed_nlinks(parent, name, os.O_RDONLY, label=f'memory checkpoint {path}', allowed_nlinks=frozenset({1, 2}))
            try:
                fcntl.flock(winner, fcntl.LOCK_EX)
                _validate_open_memory_batch_checkpoint_at(problem_id, path, parent, name, winner, current_temporary_name=temporary_name, expected_normalized_items=expected_normalized_items)
            finally:
                try:
                    fcntl.flock(winner, fcntl.LOCK_UN)
                finally:
                    os.close(winner)
        else:
            published = True
            temporary = _verify_open_regular_at(parent, temporary_name, descriptor, label=f'memory checkpoint temporary {path.parent / temporary_name}', expected_nlink=2)
            checkpoint = os.stat(name, dir_fd=parent, follow_symlinks=False)
            _validate_regular_metadata(checkpoint, label=f'memory checkpoint {path}', expected_nlink=2)
            if not _same_inode(temporary, checkpoint):
                raise ValueError('published memory checkpoint changed during linking')
        _fsync_directory_fd(parent, path.parent)
    finally:
        try:
            if descriptor is not None:
                _unlink_temporary_durable_at(parent, path.parent, temporary_name, descriptor)
            if published and descriptor is not None:
                _verify_open_regular_at(parent, name, descriptor, label=f'memory checkpoint {path}')
        finally:
            if descriptor is not None:
                try:
                    if temporary_locked:
                        fcntl.flock(descriptor, fcntl.LOCK_UN)
                finally:
                    os.close(descriptor)
            os.close(parent)
    return published

def _batch_id_for_items(problem_id: str, encoded_items: bytes, *, schema: str=MEMORY_BATCH_SCHEMA) -> str:
    if schema not in {LEGACY_MEMORY_BATCH_SCHEMA, MEMORY_BATCH_SCHEMA}:
        raise ValueError('memory batch schema is unsupported')
    material = schema.encode('utf-8') + b'\x00' + problem_id.encode('utf-8') + b'\x00' + encoded_items
    return f'batch_{hashlib.sha256(material).hexdigest()}'

def _validate_canonical_utc_timestamp(value: Any, *, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f'{label} must be a canonical UTC timestamp')
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f'{label} must be a canonical UTC timestamp') from exc
    if parsed.tzinfo is None or parsed.utcoffset() != timedelta(0):
        raise ValueError(f'{label} must be a canonical UTC timestamp')
    canonical = parsed.astimezone(timezone.utc).isoformat()
    if value != canonical:
        raise ValueError(f'{label} must be a canonical UTC timestamp')
    return value

def _memory_batch_checkpoint_sha256(payload: Dict[str, Any]) -> str:
    unsigned = dict(payload)
    unsigned.pop('checkpoint_sha256', None)
    canonical = (json.dumps(unsigned, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode('utf-8')
    return hashlib.sha256(canonical).hexdigest()

def _memory_batch_commit_sha256(payload: Mapping[str, Any]) -> str:
    unsigned = dict(payload)
    unsigned.pop('commit_sha256', None)
    canonical = (json.dumps(unsigned, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode('utf-8')
    return hashlib.sha256(canonical).hexdigest()

def _require_memory_batch_publication_open(cutoffs: tuple[float, float] | None, *, observed_wall: float | None=None, observed_monotonic: float | None=None) -> tuple[float, float]:
    wall = time.time() if observed_wall is None else observed_wall
    monotonic = time.monotonic() if observed_monotonic is None else observed_monotonic
    for value, label in ((wall, 'wall'), (monotonic, 'monotonic')):
        if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(float(value))):
            raise ValueError(f'memory checkpoint {label} clock is invalid')
    if cutoffs is not None and (float(wall) >= cutoffs[0] or float(monotonic) >= cutoffs[1]):
        raise ValueError('memory checkpoint publication window is closed')
    return (float(wall), float(monotonic))

def _batch_record_id(batch_id: str, index: int) -> str:
    digest = hashlib.sha256(f'{batch_id}\x00record\x00{index}'.encode('utf-8')).hexdigest()
    return f'mem_{digest}'

def _batch_event_id(batch_id: str) -> str:
    digest = hashlib.sha256(f'{batch_id}\x00event'.encode('utf-8')).hexdigest()
    return f'event_{digest}'

def _checkpoint_normalized_items(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [{'channel': record['channel'], 'record': record['record'], 'active': record['active'], 'supersedes': record['supersedes']} for record in payload['records']]

def _read_open_memory_batch_bytes(descriptor: int, path: Path) -> bytes:
    """Read one already-fenced checkpoint descriptor with a hard size bound."""
    os.lseek(descriptor, 0, os.SEEK_SET)
    chunks: List[bytes] = []
    total = 0
    while True:
        chunk = os.read(descriptor, 65536)
        if not chunk:
            break
        total += len(chunk)
        if total > MAX_MEMORY_BATCH_FILE_BYTES:
            raise ValueError(f'memory batch checkpoint exceeds its size limit: {path}')
        chunks.append(chunk)
    encoded = b''.join(chunks)
    if not encoded:
        raise ValueError(f'memory batch checkpoint has an invalid size: {path}')
    return encoded

def _validate_memory_batch_payload(problem_id: str, path: Path, encoded: bytes, *, require_content_addressed: bool) -> Dict[str, Any]:
    """Purely validate checkpoint bytes, including full-SHA self-authentication."""
    try:
        raw = encoded.decode('utf-8')
    except UnicodeError as exc:
        raise ValueError(f'cannot read memory batch checkpoint {path}: {exc}') from exc
    payload = _strict_json_loads(raw, label=f'memory batch checkpoint {path}')
    if not isinstance(payload, dict) or set(payload) != {'schema', 'batch_id', 'checkpoint_sha256', 'timestamp_utc', 'records', 'event'}:
        raise ValueError(f'memory batch checkpoint has an invalid envelope: {path}')
    batch_id = payload.get('batch_id')
    records = payload.get('records')
    event = payload.get('event')
    checkpoint_sha256 = payload.get('checkpoint_sha256')
    if payload.get('schema') not in {LEGACY_MEMORY_BATCH_SCHEMA, MEMORY_BATCH_SCHEMA} or not isinstance(batch_id, str) or path.name != f'{batch_id}.json' or (not isinstance(checkpoint_sha256, str)) or (re.fullmatch('[0-9a-f]{64}', checkpoint_sha256) is None) or (not isinstance(records, list)) or (not 1 <= len(records) <= MAX_MEMORY_BATCH_RECORDS) or (not isinstance(event, dict)):
        raise ValueError(f'memory batch checkpoint has invalid bindings: {path}')
    _validate_canonical_utc_timestamp(payload.get('timestamp_utc'), label=f'memory batch checkpoint timestamp {path}')
    is_content_addressed = bool(_CONTENT_ADDRESSED_BATCH_ID_RE.fullmatch(batch_id))
    if require_content_addressed and (not is_content_addressed):
        raise ValueError(f'memory batch checkpoint requires a full-SHA content-addressed batch: {path}')
    record_keys = {'record_id', 'timestamp_utc', 'channel', 'active', 'supersedes', 'batch_id', 'record'}
    appended_records: List[Dict[str, str]] = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError(f'memory batch checkpoint has a non-object record: {path}')
        if is_content_addressed and set(record) != record_keys:
            raise ValueError(f'content-addressed memory batch checkpoint is not hash-bound: {path}')
        channel = record.get('channel')
        record_id = record.get('record_id')
        if not isinstance(channel, str):
            raise ValueError(f'memory batch checkpoint has an invalid channel: {path}')
        _channel_path(problem_id, channel)
        if not isinstance(record_id, str) or not record_id or record.get('batch_id') != batch_id or (record.get('timestamp_utc') != payload['timestamp_utc']) or (not isinstance(record.get('active'), bool)) or (not isinstance(record.get('supersedes'), list)) or (not isinstance(record.get('record'), dict)):
            raise ValueError(f'memory batch checkpoint has an invalid record: {path}')
        appended_records.append({'record_id': record_id, 'channel': channel})
    event_keys = {'record_id', 'timestamp_utc', 'event_type', 'batch_id', 'active', 'supersedes', 'appended_records'}
    if is_content_addressed and (set(event) != event_keys or not isinstance(event.get('record_id'), str) or (not event.get('record_id'))) or event.get('event_type') != 'memory_append_batch' or event.get('batch_id') != batch_id or (event.get('timestamp_utc') != payload['timestamp_utc']) or (event.get('active') is not True) or (event.get('supersedes') != []) or (event.get('appended_records') != appended_records):
        raise ValueError(f'memory batch checkpoint has an invalid event: {path}')
    if is_content_addressed:
        for record in records:
            try:
                normalized_supersedes = _validate_supersedes(record['supersedes'])
            except ValueError as exc:
                raise ValueError(f'content-addressed memory batch checkpoint is not hash-bound: {path}') from exc
            if normalized_supersedes != record['supersedes']:
                raise ValueError(f'content-addressed memory batch checkpoint is not hash-bound: {path}')
        normalized_items = _checkpoint_normalized_items(payload)
        encoded_items = json.dumps(normalized_items, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
        expected_batch_id = _batch_id_for_items(sanitize_problem_id(problem_id), encoded_items, schema=str(payload['schema']))
        expected_record_ids = [_batch_record_id(batch_id, index) for index in range(len(records))]
        canonical = (json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode('utf-8')
        if batch_id != expected_batch_id or [record['record_id'] for record in records] != expected_record_ids or event.get('record_id') != _batch_event_id(batch_id) or (checkpoint_sha256 != _memory_batch_checkpoint_sha256(payload)) or (encoded != canonical):
            raise ValueError(f'content-addressed memory batch checkpoint is not hash-bound: {path}')
    return payload

def _validate_memory_batch_commit_payload(checkpoint: Mapping[str, Any], path: Path, encoded: bytes) -> Dict[str, Any]:
    if not encoded or len(encoded) > MAX_MEMORY_BATCH_COMMIT_FILE_BYTES:
        raise ValueError(f'memory batch commit marker has an invalid size: {path}')
    try:
        raw = encoded.decode('utf-8')
    except UnicodeError as exc:
        raise ValueError(f'cannot read memory batch commit marker {path}: {exc}') from exc
    payload = _strict_json_loads(raw, label=f'memory batch commit marker {path}')
    keys = {'schema', 'batch_id', 'checkpoint_sha256', 'committed_at_utc', 'committed_at_monotonic', 'commit_sha256'}
    if not isinstance(payload, dict) or set(payload) != keys:
        raise ValueError(f'memory batch commit marker has an invalid envelope: {path}')
    committed_at_utc = _validate_canonical_utc_timestamp(payload.get('committed_at_utc'), label='memory batch commit timestamp')
    committed_at_monotonic = payload.get('committed_at_monotonic')
    if payload.get('schema') != MEMORY_BATCH_COMMIT_SCHEMA or payload.get('batch_id') != checkpoint.get('batch_id') or payload.get('checkpoint_sha256') != checkpoint.get('checkpoint_sha256') or (not isinstance(committed_at_monotonic, (int, float))) or isinstance(committed_at_monotonic, bool) or (not math.isfinite(float(committed_at_monotonic))) or (float(committed_at_monotonic) <= 0) or (not isinstance(payload.get('commit_sha256'), str)) or (re.fullmatch('[0-9a-f]{64}', payload['commit_sha256']) is None) or (payload['commit_sha256'] != _memory_batch_commit_sha256(payload)):
        raise ValueError(f'memory batch commit marker has invalid bindings: {path}')
    canonical = (json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode('utf-8')
    if canonical != encoded:
        raise ValueError(f'memory batch commit marker is not canonical: {path}')
    return {**payload, 'committed_at_utc': committed_at_utc, 'committed_at_monotonic': float(committed_at_monotonic)}

def _read_memory_batch_commit(checkpoint: Mapping[str, Any], checkpoint_path: Path, *, allow_missing: bool) -> Dict[str, Any] | None:
    marker_path = _batch_commit_path(checkpoint_path)
    try:
        parent, name = _open_memory_parent(marker_path, create=False)
    except FileNotFoundError:
        if allow_missing:
            return None
        raise
    try:
        try:
            descriptor = _open_existing_regular_allowed_nlinks(parent, name, os.O_RDONLY, label=f'memory batch commit marker {marker_path}', allowed_nlinks=frozenset({1, 2}))
        except FileNotFoundError:
            if allow_missing:
                return None
            raise
        try:
            fcntl.flock(descriptor, fcntl.LOCK_EX)
            try:
                before = _verify_open_regular_allowed_nlinks(parent, name, descriptor, label=f'memory batch commit marker {marker_path}', allowed_nlinks=frozenset({1, 2}))
            except FileNotFoundError:
                if allow_missing:
                    return None
                raise
            encoded = _read_open_memory_batch_bytes(descriptor, marker_path)
            commit = _validate_memory_batch_commit_payload(checkpoint, marker_path, encoded)
            after = _verify_open_regular_allowed_nlinks(parent, name, descriptor, label=f'memory batch commit marker {marker_path}', allowed_nlinks=frozenset({1, 2}))
            if before.st_nlink != after.st_nlink:
                raise ValueError(f'memory batch commit marker changed while it was read: {marker_path}')
            if after.st_nlink == 2:
                _recover_checkpoint_orphan_at(parent, marker_path.parent, name, descriptor, None)
            _verify_open_regular_at(parent, name, descriptor, label=f'memory batch commit marker {marker_path}')
            return commit
        finally:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            finally:
                os.close(descriptor)
    finally:
        os.close(parent)

def _durably_revalidate_memory_batch_artifacts(problem_id: str, checkpoint_path: Path) -> tuple[Dict[str, Any], Dict[str, Any]]:
    """Re-read, flush, and re-bind both artifacts before any success receipt."""
    checkpoint = _validate_memory_batch_checkpoint_data(problem_id, checkpoint_path)
    commit = _read_memory_batch_commit(checkpoint, checkpoint_path, allow_missing=False)
    if commit is None:
        raise ValueError('memory batch commit marker disappeared')
    parent = _open_memory_directory(checkpoint_path.parent, create=False)
    try:
        for path in (checkpoint_path, _batch_commit_path(checkpoint_path)):
            descriptor = _open_existing_regular_allowed_nlinks(parent, path.name, os.O_RDONLY, label=f'memory batch publication artifact {path}', allowed_nlinks=frozenset({1}))
            try:
                before = os.fstat(descriptor)
                os.fsync(descriptor)
                after = _verify_open_regular_at(parent, path.name, descriptor, label=f'memory batch publication artifact {path}')
                if not _same_inode(before, after):
                    raise ValueError('memory batch publication artifact changed while flushed')
            finally:
                os.close(descriptor)
        _validate_directory_metadata(os.fstat(parent), label=f'memory checkpoint directory {checkpoint_path.parent}', require_owner=True)
        _fsync_directory_fd(parent, checkpoint_path.parent)
    finally:
        os.close(parent)
    refreshed = _validate_memory_batch_checkpoint_data(problem_id, checkpoint_path)
    refreshed_commit = _read_memory_batch_commit(refreshed, checkpoint_path, allow_missing=False)
    if refreshed_commit is None:
        raise ValueError('memory batch commit marker disappeared')
    if refreshed['checkpoint_sha256'] != checkpoint['checkpoint_sha256'] or refreshed_commit['commit_sha256'] != commit['commit_sha256']:
        raise ValueError('memory batch publication artifacts changed after flush')
    return (refreshed, refreshed_commit)

def _publish_memory_batch_commit_once(checkpoint_path: Path, checkpoint: Mapping[str, Any], *, initial_cutoffs: tuple[float, float] | None, publication_preflight: Callable[[], Mapping[str, Any] | None] | None) -> Dict[str, Any]:
    if initial_cutoffs is not None or publication_preflight is not None:
        raise ValueError('legacy MCP cannot bind host publication cutoffs')
    marker_path = _batch_commit_path(checkpoint_path)
    committed_at_wall, committed_at_monotonic = _require_memory_batch_publication_open(None)
    committed_datetime = datetime.fromtimestamp(committed_at_wall, timezone.utc)
    checkpoint_datetime = datetime.fromisoformat(str(checkpoint['timestamp_utc']))
    if committed_datetime < checkpoint_datetime:
        committed_datetime = checkpoint_datetime
    payload: Dict[str, Any] = {'schema': MEMORY_BATCH_COMMIT_SCHEMA, 'batch_id': checkpoint['batch_id'], 'checkpoint_sha256': checkpoint['checkpoint_sha256'], 'committed_at_utc': committed_datetime.astimezone(timezone.utc).isoformat(), 'committed_at_monotonic': committed_at_monotonic}
    payload['commit_sha256'] = _memory_batch_commit_sha256(payload)
    encoded = (json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode('utf-8')
    if len(encoded) > MAX_MEMORY_BATCH_COMMIT_FILE_BYTES:
        raise ValueError('encoded memory batch commit marker exceeds its size limit')
    parent, name = _open_memory_parent(marker_path, create=False)
    temporary_name = f'.{name}.{uuid.uuid4().hex}.tmp'
    descriptor: int | None = None
    temporary_locked = False
    published = False
    try:
        descriptor = _open_new_regular_at(parent, temporary_name, os.O_WRONLY, label=f'memory batch commit temporary {marker_path.parent / temporary_name}')
        fcntl.flock(descriptor, fcntl.LOCK_EX)
        temporary_locked = True
        _write_all(descriptor, encoded)
        os.fsync(descriptor)
        _verify_open_regular_at(parent, temporary_name, descriptor, label=f'memory batch commit temporary {marker_path.parent / temporary_name}')
        cutoffs = None
        _require_memory_batch_publication_open(cutoffs)
        try:
            os.link(temporary_name, name, src_dir_fd=parent, dst_dir_fd=parent, follow_symlinks=False)
        except FileExistsError:
            winner = _read_memory_batch_commit(checkpoint, checkpoint_path, allow_missing=False)
            if winner is None:
                raise ValueError('memory batch commit marker disappeared')
            return winner
        published = True
        _verify_open_regular_at(parent, name, descriptor, label=f'memory batch commit marker {marker_path}', expected_nlink=2)
        _fsync_directory_fd(parent, marker_path.parent)
    finally:
        try:
            if descriptor is not None:
                _unlink_temporary_durable_at(parent, marker_path.parent, temporary_name, descriptor)
        finally:
            if descriptor is not None:
                try:
                    if temporary_locked:
                        fcntl.flock(descriptor, fcntl.LOCK_UN)
                finally:
                    os.close(descriptor)
            os.close(parent)
    if not published:
        raise AssertionError('memory batch commit marker was not published')
    committed = _read_memory_batch_commit(checkpoint, checkpoint_path, allow_missing=False)
    if committed is None:
        raise ValueError('memory batch commit marker is not durable')
    return committed

def _validate_open_memory_batch_checkpoint_at(problem_id: str, path: Path, parent_descriptor: int, name: str, descriptor: int, *, current_temporary_name: str | None=None, expected_normalized_items: List[Dict[str, Any]] | None=None) -> Dict[str, Any]:
    """Validate a locked checkpoint and recover only its authenticated orphan."""
    label = f'memory checkpoint {path}'
    before = _verify_open_regular_allowed_nlinks(parent_descriptor, name, descriptor, label=label, allowed_nlinks=frozenset({1, 2}))
    try:
        encoded = _read_open_memory_batch_bytes(descriptor, path)
    except OSError as exc:
        raise ValueError(f'cannot read memory batch checkpoint {path}: {exc}') from exc
    after = _verify_open_regular_allowed_nlinks(parent_descriptor, name, descriptor, label=label, allowed_nlinks=frozenset({1, 2}))
    if before.st_nlink != after.st_nlink:
        raise ValueError(f'memory checkpoint changed while it was read: {path}')
    needs_recovery = after.st_nlink == 2
    payload = _validate_memory_batch_payload(problem_id, path, encoded, require_content_addressed=True)
    if expected_normalized_items is not None and _checkpoint_normalized_items(payload) != expected_normalized_items:
        raise ValueError('content-addressed memory batch checkpoint collides with different items')
    if needs_recovery:
        _recover_checkpoint_orphan_at(parent_descriptor, path.parent, name, descriptor, current_temporary_name)
    _verify_open_regular_at(parent_descriptor, name, descriptor, label=label)
    return payload

def _validate_memory_batch_checkpoint_data(problem_id: str, path: Path) -> Dict[str, Any]:
    parent, name = _open_memory_parent(path, create=False)
    try:
        descriptor = _open_existing_regular_allowed_nlinks(parent, name, os.O_RDONLY, label=f'memory checkpoint {path}', allowed_nlinks=frozenset({1, 2}))
        try:
            fcntl.flock(descriptor, fcntl.LOCK_EX)
            return _validate_open_memory_batch_checkpoint_at(problem_id, path, parent, name, descriptor)
        finally:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            finally:
                os.close(descriptor)
    finally:
        os.close(parent)

def _iter_memory_batch_checkpoints(problem_id: str, *, owner_manifest_snapshot_json: str | None=None) -> Iterable[Dict[str, Any]]:
    """Read only local committed checkpoints and compatible legacy batches."""
    if owner_manifest_snapshot_json is not None:
        raise ValueError('legacy MCP rejects owner publication snapshots')
    checkpoint_dir = _batch_checkpoint_dir(problem_id)
    try:
        descriptor = _open_memory_directory(checkpoint_dir, create=False)
    except FileNotFoundError:
        return
    try:
        names = sorted((name for name in os.listdir(descriptor) if name.startswith('batch_') and name.endswith('.json') and (not name.endswith('.commit.json'))))
        _validate_directory_metadata(os.fstat(descriptor), label=f'memory checkpoint directory {checkpoint_dir}', require_owner=True)
    finally:
        os.close(descriptor)
    for name in names:
        path = checkpoint_dir / name
        checkpoint = _validate_memory_batch_checkpoint_data(problem_id, path)
        commit = _read_memory_batch_commit(checkpoint, path, allow_missing=True)
        if commit is None:
            if checkpoint['schema'] == LEGACY_MEMORY_BATCH_SCHEMA:
                yield {**checkpoint, 'committed_at_utc': checkpoint['timestamp_utc'], 'committed_at_monotonic': None, 'commit_sha256': None, 'legacy_unmarked': True}
            continue
        yield {**checkpoint, 'committed_at_utc': commit['committed_at_utc'], 'committed_at_monotonic': commit['committed_at_monotonic'], 'commit_sha256': commit['commit_sha256'], 'publication_receipt': None, 'legacy_unmarked': False}

def _new_record_id(prefix: str='mem') -> str:
    return f'{prefix}_{uuid.uuid4().hex[:16]}'

def _validate_supersedes(supersedes: Optional[List[str]]) -> List[str]:
    if supersedes is None:
        return []
    if not isinstance(supersedes, list):
        raise ValueError('supersedes must be a JSON array of record ids')
    normalized: List[str] = []
    seen = set()
    for record_id in supersedes:
        if not isinstance(record_id, str) or not record_id.strip():
            raise ValueError('supersedes entries must be non-empty record id strings')
        cleaned = record_id.strip()
        if cleaned not in seen:
            normalized.append(cleaned)
            seen.add(cleaned)
    return normalized

def _read_supersedes(raw: Any) -> List[str]:
    """Read legacy supersedes metadata without rejecting the whole memory file."""
    if isinstance(raw, str):
        candidates = [raw]
    elif isinstance(raw, list):
        candidates = raw
    else:
        candidates = []
    normalized: List[str] = []
    seen = set()
    for candidate in candidates:
        if not isinstance(candidate, str) or not candidate.strip():
            continue
        cleaned = candidate.strip()
        if cleaned not in seen:
            normalized.append(cleaned)
            seen.add(cleaned)
    return normalized

def _legacy_record_id(channel: str, ordinal: int, item: Dict[str, Any]) -> str:
    canonical = json.dumps(item, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
    material = f'{channel}\x00{ordinal}\x00{canonical}'.encode('utf-8')
    return f'legacy_{hashlib.sha256(material).hexdigest()[:24]}'

def _load_memory_entries(problem_id: str, *, owner_manifest_snapshot_json: str | None=None) -> Dict[str, List[Dict[str, Any]]]:
    if owner_manifest_snapshot_json is not None:
        raise ValueError('legacy MCP rejects owner publication snapshots')
    raw_items_by_channel: Dict[str, List[Dict[str, Any]]] = {channel: list(_iter_jsonl(_channel_path(problem_id, channel))) for channel in CHANNEL_FILES}
    for checkpoint in _iter_memory_batch_checkpoints(problem_id, owner_manifest_snapshot_json=owner_manifest_snapshot_json):
        for item in checkpoint['records']:
            raw_items_by_channel[item['channel']].append(item)
        raw_items_by_channel['events'].append(checkpoint['event'])
    entries_by_channel: Dict[str, List[Dict[str, Any]]] = {}
    global_ordinal = 0
    for channel in CHANNEL_FILES:
        entries: List[Dict[str, Any]] = []
        for ordinal, raw_item in enumerate(raw_items_by_channel[channel]):
            raw_record_id = raw_item.get('record_id')
            if isinstance(raw_record_id, str) and raw_record_id.strip():
                record_id = raw_record_id.strip()
            else:
                record_id = _legacy_record_id(channel, ordinal, raw_item)
            raw_active = raw_item.get('active', True)
            declared_active = raw_active if isinstance(raw_active, bool) else True
            supersedes = _read_supersedes(raw_item.get('supersedes'))
            entries.append({'record_id': record_id, 'declared_active': declared_active, 'supersedes': supersedes, 'item': raw_item, 'channel': channel, 'ordinal': ordinal, 'global_ordinal': global_ordinal})
            global_ordinal += 1
        entries_by_channel[channel] = entries
    superseded_by: Dict[str, List[str]] = {}
    for entries in entries_by_channel.values():
        for entry in entries:
            for superseded_id in entry['supersedes']:
                superseders = superseded_by.setdefault(superseded_id, [])
                if entry['record_id'] not in superseders:
                    superseders.append(entry['record_id'])
    for entries in entries_by_channel.values():
        for entry in entries:
            entry['superseded_by'] = superseded_by.get(entry['record_id'], [])
            entry['effective_active'] = entry['declared_active'] and (not entry['superseded_by'])
    return entries_by_channel

def _timestamp_rank(item: Dict[str, Any]) -> float:
    raw_timestamp = item.get('timestamp_utc')
    if not isinstance(raw_timestamp, str) or not raw_timestamp.strip():
        return float('-inf')
    try:
        parsed = datetime.fromisoformat(raw_timestamp.strip().replace('Z', '+00:00'))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.timestamp()
    except ValueError:
        return float('-inf')

def _candidate_rank(candidate: Dict[str, Any], newest_first: bool) -> tuple:
    score = candidate['score']
    if newest_first:
        return (round(score, BM25_NEAR_TIE_DECIMALS), candidate['timestamp_rank'], candidate['global_ordinal'], score)
    return (score, -candidate['timestamp_rank'], -candidate['global_ordinal'])

def _compact_json_chars(value: Any) -> int:
    return len(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')))

def _memory_search_response_utf8_bytes(value: Any) -> int:
    """Size the indented JSON text emitted by the official MCP SDK."""
    return len(json.dumps(value, allow_nan=False, ensure_ascii=False, indent=2).encode('utf-8'))

def _tokenize_bm25(text: str) -> List[str]:
    return re.findall('[A-Za-z0-9_]+', text.lower())

def _bm25_score_documents(query: str, documents: List[List[str]], *, k1: float=1.5, b: float=0.75) -> List[float]:
    query_tokens = _tokenize_bm25(query)
    if not query_tokens or not documents:
        return [0.0 for _ in documents]
    query_term_counts = Counter(query_tokens)
    document_frequencies: Counter[str] = Counter()
    document_term_counts = [Counter(document) for document in documents]
    document_lengths = [len(document) for document in documents]
    avg_doc_length = sum(document_lengths) / len(document_lengths) if document_lengths else 0.0
    total_documents = len(documents)
    for document in documents:
        for token in set(document):
            document_frequencies[token] += 1
    scores: List[float] = []
    for doc_counts, doc_length in zip(document_term_counts, document_lengths):
        score = 0.0
        norm = k1 * (1.0 - b + b * (doc_length / avg_doc_length)) if avg_doc_length > 0 else k1
        for token, query_tf in query_term_counts.items():
            term_frequency = doc_counts.get(token, 0)
            if term_frequency <= 0:
                continue
            document_frequency = document_frequencies.get(token, 0)
            idf = math.log(1.0 + (total_documents - document_frequency + 0.5) / (document_frequency + 0.5))
            numerator = term_frequency * (k1 + 1.0)
            denominator = term_frequency + norm
            score += query_tf * idf * (numerator / denominator)
        scores.append(score)
    return scores

def search_matlas_theorems(query: str, num_results: int=10, endpoint: str=MATLAS_SEARCH_URL, timeout_seconds: int=30) -> Dict[str, Any]:
    normalized_query = _normalize_external_query(query)
    num_results = _validate_external_result_count(num_results)
    upstream_count = max(10, num_results)
    payload = {'query': normalized_query, 'num_results': upstream_count}
    envelope: Dict[str, Any] = {'schema_version': 'rethlas_external_retrieval_v1', 'provider': 'matlas_official_v0_1', 'provider_protocol': 'matlas_openapi_0_1_0', 'endpoint': endpoint, 'query': normalized_query, 'requested_count': num_results, 'count': 0, 'results': [], 'scope': 'published_mathematical_statements', 'mathematical_evidence_authority': False, 'fallback_used': False}
    try:
        response = requests.post(endpoint, json=payload, headers={'Accept': 'application/json', 'Content-Type': 'application/json', 'User-Agent': 'rethlas/1.0'}, timeout=timeout_seconds, stream=True)
        primary_error_pending = True
        try:
            response.raise_for_status()
            data = _read_bounded_external_json(response)
            primary_error_pending = False
        finally:
            close = getattr(response, 'close', None)
            if callable(close):
                try:
                    close()
                except Exception as error:
                    if not primary_error_pending:
                        raise _ExternalResponseCloseError from error
    except _ExternalResponseTooLarge:
        return {**envelope, 'retrieval_status': 'error', 'error': 'response_too_large'}
    except _ExternalResponseCloseError:
        return {**envelope, 'retrieval_status': 'error', 'error': 'network response_close_failed'}
    except requests.HTTPError as error:
        status = error.response.status_code if error.response is not None else 'unknown'
        return {**envelope, 'retrieval_status': 'error', 'error': f'http {status}'}
    except ValueError:
        return {**envelope, 'retrieval_status': 'error', 'error': 'invalid_json'}
    except requests.RequestException as error:
        return {**envelope, 'retrieval_status': 'error', 'error': f'network {type(error).__name__}'}
    if not isinstance(data, list):
        return {**envelope, 'retrieval_status': 'error', 'error': f'invalid_response_type:{type(data).__name__}'}
    required_string_fields = ('entity_name', 'doi', 'title', 'authors', 'journal', 'year', 'statement', 'candidate_id')
    normalized: List[Dict[str, str]] = []
    for index, item in enumerate(data):
        if not isinstance(item, dict):
            return {**envelope, 'retrieval_status': 'error', 'error': f'invalid_result:{index}:not_object'}
        source_type = item.get('type')
        if not isinstance(source_type, str) or source_type not in {'book', 'paper'}:
            return {**envelope, 'retrieval_status': 'error', 'error': f'invalid_result:{index}:type'}
        if any((not isinstance(item.get(field), str) for field in required_string_fields)):
            return {**envelope, 'retrieval_status': 'error', 'error': f'invalid_result:{index}:fields'}
        if not _external_fields_are_utf8(item, required_string_fields):
            return {**envelope, 'retrieval_status': 'error', 'error': f'invalid_result:{index}:encoding'}
        normalized.append({'type': source_type, **{field: item[field] for field in required_string_fields}})
    normalized = normalized[:num_results]
    result = {**envelope, 'count': len(normalized), 'results': normalized, 'retrieval_status': 'ok'}
    if len(canonical_json_bytes(result)) > MAX_EXTERNAL_SUCCESS_UTF8_BYTES:
        return {**envelope, 'retrieval_status': 'error', 'error': 'response_too_large'}
    return result

def search_arxiv_theorems(query: str, num_results: int=10, endpoint: str=LEGACY_ARXIV_THEOREM_URL, timeout_seconds: int=30) -> Dict[str, Any]:
    """Query Danus's historical arXiv theorem service without implicit fallback."""
    normalized_query = _normalize_external_query(query)
    num_results = _validate_external_result_count(num_results)
    envelope: Dict[str, Any] = {'schema_version': 'rethlas_external_retrieval_v1', 'provider': 'danus_legacy_arxiv_theorem_v1', 'provider_protocol': 'danus_legacy_arxiv_theorem_search_v1', 'endpoint': endpoint, 'query': normalized_query, 'requested_count': num_results, 'count': 0, 'results': [], 'scope': 'arxiv_theorem_snippets', 'mathematical_evidence_authority': False, 'fallback_used': False}
    try:
        response = requests.post(endpoint, json={'query': normalized_query, 'task': THEOREM_SEARCH_TASK, 'num_results': num_results}, headers={'Accept': 'application/json', 'Content-Type': 'application/json', 'User-Agent': 'rethlas/1.0'}, timeout=timeout_seconds, stream=True)
        primary_error_pending = True
        try:
            response.raise_for_status()
            data = _read_bounded_external_json(response)
            primary_error_pending = False
        finally:
            close = getattr(response, 'close', None)
            if callable(close):
                try:
                    close()
                except Exception as error:
                    if not primary_error_pending:
                        raise _ExternalResponseCloseError from error
    except _ExternalResponseTooLarge:
        return {**envelope, 'retrieval_status': 'error', 'error': 'response_too_large'}
    except _ExternalResponseCloseError:
        return {**envelope, 'retrieval_status': 'error', 'error': 'network response_close_failed'}
    except requests.HTTPError as error:
        status = error.response.status_code if error.response is not None else 'unknown'
        return {**envelope, 'retrieval_status': 'error', 'error': f'http {status}'}
    except ValueError:
        return {**envelope, 'retrieval_status': 'error', 'error': 'invalid_json'}
    except requests.RequestException as error:
        return {**envelope, 'retrieval_status': 'error', 'error': f'network {type(error).__name__}'}
    if not isinstance(data, list):
        return {**envelope, 'retrieval_status': 'error', 'error': f'invalid_response_type:{type(data).__name__}'}
    required_fields = ('title', 'theorem', 'arxiv_id', 'theorem_id')
    normalized: List[Dict[str, str]] = []
    for index, item in enumerate(data):
        if not isinstance(item, dict) or any((not isinstance(item.get(field), str) for field in required_fields)):
            return {**envelope, 'retrieval_status': 'error', 'error': f'invalid_result:{index}'}
        if not _external_fields_are_utf8(item, required_fields):
            return {**envelope, 'retrieval_status': 'error', 'error': f'invalid_result:{index}:encoding'}
        normalized.append({field: item[field] for field in required_fields})
    normalized = normalized[:num_results]
    result = {**envelope, 'count': len(normalized), 'results': normalized, 'retrieval_status': 'ok'}
    if len(canonical_json_bytes(result)) > MAX_EXTERNAL_SUCCESS_UTF8_BYTES:
        return {**envelope, 'retrieval_status': 'error', 'error': 'response_too_large'}
    return result

def _read_bounded_external_bytes(response: requests.Response, *, maximum_bytes: int) -> bytes:
    """Read one remote body without trusting Content-Length or decompression size."""
    headers = getattr(response, 'headers', {})
    content_length = headers.get('Content-Length') if hasattr(headers, 'get') else None
    if isinstance(content_length, str) and content_length.isdigit():
        if int(content_length) > maximum_bytes:
            raise _ExternalResponseTooLarge
    iter_content = getattr(response, 'iter_content', None)
    if callable(iter_content):
        chunks: List[bytes] = []
        total = 0
        for chunk in iter_content(chunk_size=16384):
            if not chunk:
                continue
            if not isinstance(chunk, bytes):
                raise ValueError('external response chunk must be bytes')
            total += len(chunk)
            if total > maximum_bytes:
                raise _ExternalResponseTooLarge
            chunks.append(chunk)
        return b''.join(chunks)
    body = getattr(response, 'content', None)
    if not isinstance(body, bytes):
        raise ValueError('external response body must be bytes')
    if len(body) > maximum_bytes:
        raise _ExternalResponseTooLarge
    return body

def _fetch_bounded_external_bytes(url: str, *, timeout_seconds: int, maximum_bytes: int, params: Optional[Dict[str, str]]=None) -> bytes:
    """GET and close one bounded external response, preserving the first failure."""
    response = requests.get(url, params=params, headers={'Accept': 'application/atom+xml,text/html;q=0.9', 'User-Agent': 'rethlas/1.0'}, timeout=timeout_seconds, stream=True)
    primary_error_pending = True
    try:
        response.raise_for_status()
        body = _read_bounded_external_bytes(response, maximum_bytes=maximum_bytes)
        primary_error_pending = False
        return body
    finally:
        close = getattr(response, 'close', None)
        if callable(close):
            try:
                close()
            except Exception as error:
                if not primary_error_pending:
                    raise _ExternalResponseCloseError from error

def _normalize_arxiv_id(arxiv_id: Any) -> str:
    if not isinstance(arxiv_id, str):
        raise ValueError('arxiv_id must be a string')
    normalized = arxiv_id.strip()
    if ARXIV_ID_RE.fullmatch(normalized) is None:
        raise ValueError('arxiv_id must be one exact modern or legacy arXiv id')
    return normalized

def _arxiv_base_id_key(arxiv_id: str) -> str:
    """Return the case-insensitive paper identity shared by all versions."""
    return re.sub('v[1-9][0-9]*$', '', _normalize_arxiv_id(arxiv_id)).casefold()

def _normalize_arxiv_locator(locator: Any) -> str:
    if not isinstance(locator, str):
        raise ValueError('locator must be a string')
    normalized = locator.strip()
    if not normalized:
        raise ValueError('locator must be non-empty')
    try:
        encoded = normalized.encode('utf-8')
    except UnicodeEncodeError as error:
        raise ValueError('locator must be valid UTF-8') from error
    if len(encoded) > 1024:
        raise ValueError('locator exceeds the 1024-byte limit')
    return normalized

def _normalize_iso_date(value: Any, *, label: str) -> Optional[str]:
    if value is None:
        return None
    if not isinstance(value, str):
        raise ValueError(f'{label} must be an ISO date')
    normalized = value.strip()
    try:
        parsed = datetime.strptime(normalized, '%Y-%m-%d')
    except ValueError as error:
        raise ValueError(f'{label} must be an ISO date') from error
    return parsed.date().isoformat()

def _arxiv_atom_entry(raw: bytes, *, expected_arxiv_id: str) -> Dict[str, str]:
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError as error:
        raise ValueError('arXiv metadata is not UTF-8') from error
    entry_match = re.search('(?is)<entry\\b[^>]*>(.*?)</entry>', text)
    if entry_match is None:
        raise ValueError('arXiv metadata has no entry')
    entry = entry_match.group(1)

    def field(name: str) -> str:
        match = re.search(f'(?is)<{name}\\b[^>]*>(.*?)</{name}>', entry)
        if match is None:
            raise ValueError(f'arXiv metadata has no {name}')
        without_tags = re.sub('(?s)<[^>]+>', ' ', match.group(1))
        return ' '.join(html.unescape(without_tags).split())
    entry_url = field('id')
    entry_id_match = re.fullmatch('https?://arxiv\\.org/abs/(.+)', entry_url, flags=re.IGNORECASE)
    if entry_id_match is None:
        raise ValueError('arXiv metadata entry id is invalid')
    entry_arxiv_id = _normalize_arxiv_id(entry_id_match.group(1))
    if _arxiv_base_id_key(entry_arxiv_id) != _arxiv_base_id_key(expected_arxiv_id):
        raise ValueError('arXiv metadata entry id differs from the requested id')
    published = field('published')
    initial_submission_date = _normalize_iso_date(published[:10], label='arXiv published date')
    if initial_submission_date is None:
        raise ValueError('arXiv metadata has no published date')
    return {'metadata_arxiv_id': entry_arxiv_id, 'title': field('title'), 'published': published, 'updated': field('updated'), 'initial_submission_date': initial_submission_date}

def _arxiv_atom_entries(raw: bytes, *, expected_arxiv_ids: List[str]) -> List[Dict[str, str]]:
    """Parse one bounded Atom response into the exact requested id order."""
    if not 1 <= len(expected_arxiv_ids) <= 10:
        raise ValueError('arXiv metadata batch must contain between 1 and 10 ids')
    normalized_expected = [_normalize_arxiv_id(arxiv_id) for arxiv_id in expected_arxiv_ids]
    expected_by_key: Dict[str, str] = {}
    for arxiv_id in normalized_expected:
        key = _arxiv_base_id_key(arxiv_id)
        if key in expected_by_key:
            raise ValueError('arXiv metadata batch contains duplicate requested ids')
        expected_by_key[key] = arxiv_id
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError as error:
        raise ValueError('arXiv metadata is not UTF-8') from error
    entry_blocks = re.findall('(?is)<entry\\b[^>]*>.*?</entry>', text)
    if not entry_blocks:
        raise ValueError('arXiv metadata has no entry')
    parsed_by_key: Dict[str, Dict[str, str]] = {}
    for entry_block in entry_blocks:
        id_match = re.search('(?is)<id\\b[^>]*>(.*?)</id>', entry_block)
        if id_match is None:
            raise ValueError('arXiv metadata has no id')
        entry_url = ' '.join(html.unescape(re.sub('(?s)<[^>]+>', ' ', id_match.group(1))).split())
        entry_id_match = re.fullmatch('https?://arxiv\\.org/abs/(.+)', entry_url, flags=re.IGNORECASE)
        if entry_id_match is None:
            raise ValueError('arXiv metadata entry id is invalid')
        observed_id = _normalize_arxiv_id(entry_id_match.group(1))
        key = _arxiv_base_id_key(observed_id)
        expected_id = expected_by_key.get(key)
        if expected_id is None:
            raise ValueError('arXiv metadata contains an unrequested entry')
        if key in parsed_by_key:
            raise ValueError('arXiv metadata contains a duplicate entry')
        parsed_by_key[key] = _arxiv_atom_entry(entry_block.encode('utf-8'), expected_arxiv_id=expected_id)
    if set(parsed_by_key) != set(expected_by_key):
        raise ValueError('arXiv metadata is missing a requested entry')
    return [parsed_by_key[_arxiv_base_id_key(arxiv_id)] for arxiv_id in normalized_expected]

def _arxiv_html_plain_text(raw: bytes) -> str:
    try:
        source = raw.decode('utf-8')
    except UnicodeDecodeError as error:
        raise ValueError('arXiv HTML is not UTF-8') from error

    def math_alt(match: re.Match[str]) -> str:
        attributes = match.group(1)
        alt_match = re.search('\\balttext\\s*=\\s*(?:\\"([^\\"]*)\\"|\'([^\']*)\')', attributes, flags=re.IGNORECASE)
        if alt_match is None:
            return ' '
        return ' ' + html.unescape(alt_match.group(1) or alt_match.group(2)) + ' '
    source = re.sub('(?is)<math\\b([^>]*)>.*?</math>', math_alt, source)
    source = re.sub('(?is)<(?:script|style|noscript)\\b[^>]*>.*?</(?:script|style|noscript)>', ' ', source)
    source = re.sub('(?i)</(?:address|article|aside|blockquote|br|dd|div|dl|dt|figcaption|figure|footer|h[1-6]|header|hr|li|main|nav|ol|p|pre|section|table|tbody|td|th|thead|tr|ul)\\s*>', '\n', source)
    source = re.sub('(?s)<[^>]+>', ' ', source)
    source = html.unescape(source).replace('\r\n', '\n').replace('\r', '\n')
    lines = [' '.join(line.split()) for line in source.split('\n')]
    compact: List[str] = []
    for line in lines:
        if line:
            compact.append(line)
        elif compact and compact[-1] != '':
            compact.append('')
    return '\n'.join(compact).strip()

def _utf8_prefix(value: str, maximum_bytes: int) -> str:
    encoded = value.encode('utf-8')
    if len(encoded) <= maximum_bytes:
        return value
    return encoded[:maximum_bytes].decode('utf-8', errors='ignore')

def _arxiv_locator_excerpts(text: str, *, locator: str, maximum_bytes: int) -> tuple[bool, str, List[Dict[str, Any]]]:
    folded = text.casefold()
    needle = locator.casefold()
    positions: List[int] = []
    cursor = 0
    while len(positions) < 3:
        position = folded.find(needle, cursor)
        if position < 0:
            break
        if not positions or position - positions[-1] > 256:
            positions.append(position)
        cursor = position + max(1, len(needle))
    match_kind = 'exact'
    if not positions:
        tokens = [token for token in re.findall('[A-Za-z0-9.]+', locator.casefold()) if len(token) >= 3]
        paragraphs = [part.strip() for part in text.split('\n\n') if part.strip()]
        scored: List[tuple[int, int, str]] = []
        offset = 0
        for paragraph in paragraphs:
            paragraph_folded = paragraph.casefold()
            score = sum((token in paragraph_folded for token in tokens))
            if score:
                scored.append((score, -offset, paragraph))
            offset += len(paragraph) + 2
        scored.sort(reverse=True)
        excerpts = [{'occurrence': index + 1, 'start_char': None, 'end_char': None, 'text': paragraph} for index, (_score, _offset, paragraph) in enumerate(scored[:3])]
        match_kind = 'token_overlap' if excerpts else 'none'
        if excerpts:
            per_excerpt = max(256, maximum_bytes // len(excerpts))
            for excerpt in excerpts:
                excerpt['text'] = _utf8_prefix(excerpt['text'], per_excerpt)
        return (False, match_kind, excerpts)
    per_excerpt = max(512, maximum_bytes // len(positions))
    excerpts = []
    for index, position in enumerate(positions):
        left = max(0, position - per_excerpt // 3)
        paragraph_left = text.rfind('\n\n', left, position)
        if paragraph_left >= 0:
            left = paragraph_left + 2
        right = min(len(text), left + per_excerpt)
        excerpt_text = _utf8_prefix(text[left:right].strip(), per_excerpt)
        excerpts.append({'occurrence': index + 1, 'start_char': left, 'end_char': left + len(excerpt_text), 'text': excerpt_text})
    return (True, match_kind, excerpts)

def read_arxiv_primary(arxiv_id: str, locator: str, max_excerpt_bytes: int=20000, latest_initial_submission_date: Optional[str]=None, metadata_endpoint: str=ARXIV_API_URL, html_endpoint_template: str=ARXIV_HTML_URL_TEMPLATE, timeout_seconds: int=30) -> Dict[str, Any]:
    """Read a bounded locator excerpt from official arXiv primary-source HTML."""
    normalized_id = _normalize_arxiv_id(arxiv_id)
    normalized_locator = _normalize_arxiv_locator(locator)
    cutoff = _normalize_iso_date(latest_initial_submission_date, label='latest_initial_submission_date')
    if isinstance(max_excerpt_bytes, bool) or not isinstance(max_excerpt_bytes, int) or (not 1000 <= max_excerpt_bytes <= MAX_ARXIV_PRIMARY_EXCERPT_BYTES):
        raise ValueError(f'max_excerpt_bytes must be an integer between 1000 and {MAX_ARXIV_PRIMARY_EXCERPT_BYTES}')
    if html_endpoint_template.count('{arxiv_id}') != 1:
        raise ValueError('arXiv HTML endpoint template must contain {arxiv_id} once')
    envelope: Dict[str, Any] = {'schema_version': 'rethlas_arxiv_primary_excerpt_v1', 'provider': 'arxiv_official_html_v1', 'arxiv_id': normalized_id, 'locator': normalized_locator, 'latest_initial_submission_date': cutoff, 'metadata_endpoint': metadata_endpoint, 'source_url': html_endpoint_template.format(arxiv_id=normalized_id), 'primary_source_text': False, 'mathematical_evidence_authority': False, 'fallback_used': False, 'excerpts': []}
    try:
        metadata_raw = _fetch_bounded_external_bytes(metadata_endpoint, params={'id_list': normalized_id}, timeout_seconds=timeout_seconds, maximum_bytes=MAX_ARXIV_METADATA_BYTES)
        metadata = _arxiv_atom_entry(metadata_raw, expected_arxiv_id=normalized_id)
    except _ExternalResponseTooLarge:
        return {**envelope, 'retrieval_status': 'error', 'error': 'metadata_too_large'}
    except _ExternalResponseCloseError:
        return {**envelope, 'retrieval_status': 'error', 'error': 'network response_close_failed'}
    except requests.HTTPError as error:
        status = error.response.status_code if error.response is not None else 'unknown'
        return {**envelope, 'retrieval_status': 'error', 'error': f'metadata_http {status}'}
    except requests.RequestException as error:
        return {**envelope, 'retrieval_status': 'error', 'error': f'network {type(error).__name__}'}
    except ValueError as error:
        return {**envelope, 'retrieval_status': 'error', 'error': str(error)}
    dated_envelope = {**envelope, **metadata}
    if cutoff is not None and metadata['initial_submission_date'] > cutoff:
        return {**dated_envelope, 'retrieval_status': 'blocked', 'error': 'initial_submission_after_cutoff'}
    try:
        html_raw = _fetch_bounded_external_bytes(envelope['source_url'], timeout_seconds=timeout_seconds, maximum_bytes=MAX_ARXIV_HTML_BYTES)
        plain_text = _arxiv_html_plain_text(html_raw)
        locator_found, match_kind, excerpts = _arxiv_locator_excerpts(plain_text, locator=normalized_locator, maximum_bytes=max_excerpt_bytes)
    except _ExternalResponseTooLarge:
        return {**dated_envelope, 'retrieval_status': 'error', 'error': 'html_too_large'}
    except _ExternalResponseCloseError:
        return {**dated_envelope, 'retrieval_status': 'error', 'error': 'network response_close_failed'}
    except requests.HTTPError as error:
        status = error.response.status_code if error.response is not None else 'unknown'
        return {**dated_envelope, 'retrieval_status': 'error', 'error': f'html_http {status}'}
    except requests.RequestException as error:
        return {**dated_envelope, 'retrieval_status': 'error', 'error': f'network {type(error).__name__}'}
    except ValueError as error:
        return {**dated_envelope, 'retrieval_status': 'error', 'error': str(error)}
    result = {**dated_envelope, 'retrieval_status': 'ok', 'primary_source_text': True, 'source_sha256': hashlib.sha256(html_raw).hexdigest(), 'source_utf8_bytes': len(html_raw), 'locator_found': locator_found, 'match_kind': match_kind, 'excerpts': excerpts}
    if len(canonical_json_bytes(result)) > MAX_EXTERNAL_SUCCESS_UTF8_BYTES:
        return {**dated_envelope, 'retrieval_status': 'error', 'error': 'response_too_large'}
    return result

def _trusted_problem_statement(problem_id: str) -> tuple[str, str]:
    sanitized_problem_id = validate_verified_problem_id(problem_id)
    expected_problem_id = os.getenv('RETHLAS_EXPECTED_PROBLEM_ID')
    if expected_problem_id and sanitized_problem_id != expected_problem_id:
        raise ValueError('problem_id does not match the runner-bound problem')
    data_root = DATA_ROOT.resolve()
    source_path = DATA_ROOT / f'{sanitized_problem_id}.md'
    resolved_source = source_path.resolve(strict=True)
    if not resolved_source.is_relative_to(data_root) or source_path.is_symlink():
        raise ValueError('problem source must be a regular file inside data root')
    descriptor = os.open(source_path, os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0))
    try:
        metadata = os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode):
            raise ValueError('problem source must be a regular file')
        if metadata.st_size > 400000:
            raise ValueError('problem source is too large')
        raw_statement = os.read(descriptor, 400001)
        if len(raw_statement) > 400000:
            raise ValueError('problem source is too large')
    finally:
        os.close(descriptor)
    try:
        statement = raw_statement.decode('utf-8')
    except UnicodeDecodeError as exc:
        raise ValueError('problem source must be valid UTF-8') from exc
    if not statement.strip():
        raise ValueError('problem source must be non-empty')
    if len(statement) > 100000:
        raise ValueError('problem source exceeds verifier statement limit')
    statement_digest = hashlib.sha256(raw_statement).hexdigest()
    expected_digest = os.getenv('RETHLAS_EXPECTED_STATEMENT_SHA256')
    if expected_digest and statement_digest != expected_digest:
        raise ValueError('problem source changed after the runner bound its digest')
    return (statement, statement_digest)

def _statement_bound_arxiv_cutoff(problem_id: str, *, expected_statement_sha256: Optional[str]=None) -> Optional[str]:
    statement, statement_digest = _trusted_problem_statement(problem_id)
    if expected_statement_sha256 is not None and statement_digest != expected_statement_sha256:
        raise ValueError('problem source differs from the caller-bound digest')
    headings = list(re.finditer('(?im)^##[ \\t]+retrieval[ \\t]+restriction[ \\t]*\\r?$', statement))
    if len(headings) != 1:
        raise ValueError('problem does not contain one retrieval control section')
    body = statement[headings[0].end():]
    if re.search('(?m)^#{1,2}[ \\t]+\\S', body):
        raise ValueError('retrieval control section must be trailing')
    explicitly_permitted = re.search('(?im)^[ \\t]*matlas and arxiv retrieval are permitted\\.(?:[ \\t]|$)', body) is not None
    denial_markers = ('strictly offline', 'strictly closed-book', 'matlas and arxiv retrieval are forbidden', 'matlas and arxiv retrieval are not permitted')
    explicitly_denied = any((marker in statement.casefold() for marker in denial_markers))
    if explicitly_permitted and explicitly_denied:
        raise ValueError('problem retrieval directives conflict')
    if not explicitly_permitted:
        raise ValueError('problem does not permit Matlas/arXiv retrieval')
    matches = re.findall('(?i)(?:initial submission date is later than|submitted after)\\s+([0-9]{4}-[0-9]{2}-[0-9]{2})', body)
    normalized = {_normalize_iso_date(value, label='statement arXiv cutoff') for value in matches}
    if len(normalized) > 1:
        raise ValueError('problem contains conflicting arXiv cutoff dates')
    return next(iter(normalized), None)

def search_arxiv_theorems_for_problem(problem_id: str, query: str, num_results: int=10, expected_statement_sha256: Optional[str]=None) -> Dict[str, Any]:
    """Search snippets only after official metadata passes the problem cutoff."""
    num_results = _validate_external_result_count(num_results)
    if num_results > 10:
        raise ValueError('problem-bound arXiv search permits at most 10 results')
    cutoff = _statement_bound_arxiv_cutoff(problem_id, expected_statement_sha256=expected_statement_sha256)
    searched = search_arxiv_theorems(query=query, num_results=num_results)
    envelope = {**searched, 'latest_initial_submission_date': cutoff, 'cutoff_enforced': cutoff is not None, 'metadata_verified': False, 'blocked_after_cutoff': 0}
    if searched.get('retrieval_status') != 'ok':
        return envelope
    raw_results = searched.get('results')
    if not isinstance(raw_results, list):
        return {**envelope, 'count': 0, 'results': [], 'retrieval_status': 'error', 'error': 'search_results_not_a_list'}
    if len(raw_results) > num_results:
        return {**envelope, 'count': 0, 'results': [], 'retrieval_status': 'error', 'error': 'search_results_exceed_requested_count'}
    normalized_ids: List[str] = []
    for index, item in enumerate(raw_results):
        if not isinstance(item, dict) or not isinstance(item.get('arxiv_id'), str):
            return {**envelope, 'count': 0, 'results': [], 'retrieval_status': 'error', 'error': f'invalid_result:{index}:arxiv_id'}
        try:
            normalized_ids.append(_normalize_arxiv_id(item['arxiv_id']))
        except ValueError as exc:
            return {**envelope, 'count': 0, 'results': [], 'retrieval_status': 'error', 'error': str(exc)}
    if not normalized_ids:
        return {**envelope, 'count': 0, 'results': [], 'retrieval_status': 'ok', 'metadata_verified': True}
    metadata_request_ids: List[str] = []
    seen_metadata_ids: set[str] = set()
    for arxiv_id in normalized_ids:
        base_id = _arxiv_base_id_key(arxiv_id)
        if base_id in seen_metadata_ids:
            continue
        seen_metadata_ids.add(base_id)
        metadata_request_ids.append(arxiv_id)
    try:
        metadata_raw = _fetch_bounded_external_bytes(ARXIV_API_URL, params={'id_list': ','.join(metadata_request_ids)}, timeout_seconds=30, maximum_bytes=MAX_ARXIV_METADATA_BYTES)
        metadata_entries = _arxiv_atom_entries(metadata_raw, expected_arxiv_ids=metadata_request_ids)
    except _ExternalResponseTooLarge:
        error = 'metadata_too_large'
    except _ExternalResponseCloseError:
        error = 'network response_close_failed'
    except requests.HTTPError as exc:
        status = exc.response.status_code if exc.response is not None else 'unknown'
        error = f'metadata_http {status}'
    except requests.RequestException as exc:
        error = f'network {type(exc).__name__}'
    except ValueError as exc:
        error = str(exc)
    else:
        verified: List[Dict[str, str]] = []
        blocked = 0
        metadata_by_id = {_arxiv_base_id_key(arxiv_id): metadata for arxiv_id, metadata in zip(metadata_request_ids, metadata_entries)}
        for item, arxiv_id in zip(raw_results, normalized_ids):
            metadata = metadata_by_id[_arxiv_base_id_key(arxiv_id)]
            if cutoff is not None and metadata['initial_submission_date'] > cutoff:
                blocked += 1
                continue
            verified.append({**{key: str(value) for key, value in item.items()}, 'metadata_arxiv_id': metadata['metadata_arxiv_id'], 'initial_submission_date': metadata['initial_submission_date']})
        result = {**envelope, 'count': len(verified), 'results': verified, 'retrieval_status': 'ok', 'metadata_verified': True, 'blocked_after_cutoff': blocked}
        if len(canonical_json_bytes(result)) > MAX_EXTERNAL_SUCCESS_UTF8_BYTES:
            return {**envelope, 'count': 0, 'results': [], 'retrieval_status': 'error', 'error': 'response_too_large'}
        return result
    return {**envelope, 'count': 0, 'results': [], 'retrieval_status': 'error', 'error': error}

def read_arxiv_primary_for_problem(problem_id: str, arxiv_id: str, locator: str, max_excerpt_bytes: int=20000, expected_statement_sha256: Optional[str]=None) -> Dict[str, Any]:
    """Read official arXiv text under the authoritative statement's cutoff."""
    cutoff = _statement_bound_arxiv_cutoff(problem_id, expected_statement_sha256=expected_statement_sha256)
    return read_arxiv_primary(arxiv_id=arxiv_id, locator=locator, max_excerpt_bytes=max_excerpt_bytes, latest_initial_submission_date=cutoff)

def verify_blueprint_service(problem_id: str, endpoint: str=VERIFY_PROOF_URL, timeout_seconds: int=3600) -> Dict[str, Any]:
    """Verify a draft against its trusted data file and publish with a receipt."""
    sanitized_problem_id = validate_verified_problem_id(problem_id)
    phase = _reasoning_phase_preflight('verify_blueprint_service')
    verification_deadline_utc = (datetime.now(timezone.utc) + timedelta(seconds=min(timeout_seconds, 3600))).isoformat() if phase is None else phase['hard_stop_at_utc']
    _validate_canonical_utc_timestamp(verification_deadline_utc, label='whole-blueprint verification hard stop')
    statement, _statement_digest = _trusted_problem_statement(sanitized_problem_id)
    results_root = Path(os.path.abspath(os.fspath(RESULTS_ROOT)))
    result_dir = results_root.joinpath(*sanitized_problem_id.split('/'))
    receipts_root = RECEIPTS_ROOT.resolve()
    if receipts_root.is_relative_to(REPO_ROOT.resolve()):
        raise ValueError('trusted receipt root must be outside the generation workspace')
    receipt_path = (receipts_root / f'{sanitized_problem_id}.json').resolve()
    if not receipt_path.is_relative_to(receipts_root):
        raise ValueError('problem_id resolves outside receipt root')
    try:
        return verify_blueprint_file(statement=statement, draft_path=result_dir / 'blueprint.md', verified_path=result_dir / 'blueprint_verified.md', endpoint=endpoint, verification_deadline_utc=verification_deadline_utc, timeout_seconds=timeout_seconds, api_token=os.getenv('VERIFY_API_TOKEN') or None, receipt_path=receipt_path, problem_id=sanitized_problem_id, blueprint_root=results_root, publication_state_root=GENERATION_CONTROL_ROOT / 'publication_transactions')
    except (ProofParseError, PublicationProofParseError) as exc:
        return {'schema_version': 'rethlas_blueprint_preflight_failure_v1', 'status': 'preflight_failed', 'category': 'blueprint_contract', 'operation': 'verify_blueprint_service', 'problem_id': sanitized_problem_id, 'error': str(exc), 'repair_hint': "Repair blueprint.md to use paper-like H1 proof items with one explicit rethlas-depends-on comment each. The final item's ## statement must exactly equal the canonical problem target; put explanations, qualifications, and paraphrases in ## proof.", 'retry_allowed': True, 'verifier_dispatched': False, 'published': False}

def memory_init(problem_id: str, meta: Optional[Dict[str, Any]]=None) -> Dict[str, Any]:
    sanitized_problem_id = sanitize_problem_id(problem_id)
    problem_dir = _problem_dir(sanitized_problem_id)
    _ensure_memory_directory_durable(problem_dir)
    lock_descriptor = _open_durable_lock_file(problem_dir / '.meta.lock')
    try:
        fcntl.flock(lock_descriptor, fcntl.LOCK_EX)
    except BaseException:
        os.close(lock_descriptor)
        raise
    try:
        _verify_open_memory_file(problem_dir / '.meta.lock', lock_descriptor, label=f"memory lock {problem_dir / '.meta.lock'}")
        created_files: Dict[str, str] = {}
        for channel, filename in CHANNEL_FILES.items():
            channel_path = problem_dir / filename
            _ensure_empty_file_durable(channel_path)
            created_files[channel] = str(channel_path)
        meta_path = problem_dir / 'meta.json'
        existing_meta: Dict[str, Any] = {}
        encoded_meta = _read_memory_bytes(meta_path, allow_missing=True)
        if encoded_meta is not None:
            try:
                raw_meta = encoded_meta.decode('utf-8')
            except UnicodeDecodeError as exc:
                raise ValueError('memory metadata must be valid UTF-8') from exc
            loaded = _strict_json_loads(raw_meta, label=f'memory metadata {meta_path}')
            if not isinstance(loaded, dict):
                raise ValueError('memory metadata must be a JSON object')
            existing_meta = loaded
        now_utc = _utc_now()
        merged_meta: Dict[str, Any] = dict(existing_meta)
        if meta:
            merged_meta.update(meta)
        merged_meta['problem_id'] = sanitized_problem_id
        merged_meta['created_at_utc'] = existing_meta.get('created_at_utc', now_utc)
        merged_meta['updated_at_utc'] = now_utc
        _write_atomic_json_replace(meta_path, merged_meta)
    finally:
        try:
            _verify_open_memory_file(problem_dir / '.meta.lock', lock_descriptor, label=f"memory lock {problem_dir / '.meta.lock'}")
        finally:
            try:
                fcntl.flock(lock_descriptor, fcntl.LOCK_UN)
            finally:
                os.close(lock_descriptor)
    return {'problem_id': sanitized_problem_id, 'memory_dir': str(problem_dir), 'meta_path': str(meta_path), 'channels': created_files}

def memory_append(problem_id: str, channel: str, record: Dict[str, Any], active: bool=True, supersedes: Optional[List[str]]=None, return_mode: str='metadata') -> Dict[str, Any]:
    """Append one offline/local fact and return a compact legacy receipt.

    ``supersedes`` is append-only metadata: referenced records are treated as
    inactive by searches, while legacy records without lifecycle metadata remain
    active by default. Released runs must use ``memory_append_batch`` so the host
    publication registry can make the write authoritative.
    """
    if channel == 'failed_paths' and isinstance(record, dict) and (record.get('schema_version') == 'rethlas_round_failure_synthesis_v1' or record.get('record_type') == 'key_failures_summary'):
        raise ValueError('round failure synthesis requires one content-addressed memory_append_batch checkpoint')
    if _released_memory_registry_configured():
        raise ValueError('memory_append is offline-only; released runs require memory_append_batch')
    if channel in _CONTROL_ONLY_MEMORY_CHANNELS or _is_route_transition_projection(channel, record):
        raise ValueError(f'{channel} is reserved for trusted control publication')
    if not isinstance(record, dict):
        raise ValueError('record must be a JSON object')
    _validate_route_terminal_memory_record(channel, record)
    if not isinstance(active, bool):
        raise ValueError('active must be a boolean')
    if not isinstance(return_mode, str) or return_mode not in {'metadata', 'full'}:
        raise ValueError("return_mode must be either 'metadata' or 'full'")
    normalized_supersedes = _validate_supersedes(supersedes)
    target = _channel_path(problem_id, channel)
    memory_init(problem_id)
    record_id = _new_record_id()
    entry = {'record_id': record_id, 'timestamp_utc': _utc_now(), 'channel': channel, 'active': active, 'supersedes': normalized_supersedes, 'record': record}
    _append_jsonl(target, entry)
    if channel != 'events':
        event_entry = {'record_id': _new_record_id('event'), 'timestamp_utc': _utc_now(), 'event_type': 'memory_append', 'channel': channel, 'active': True, 'supersedes': [], 'appended_record_id': record_id}
        _append_jsonl(_channel_path(problem_id, 'events'), event_entry)
    response = {'status': 'ok', 'problem_id': sanitize_problem_id(problem_id), 'record_id': record_id, 'timestamp_utc': entry['timestamp_utc'], 'channel': channel, 'path': str(target), 'active': active, 'supersedes': normalized_supersedes}
    if return_mode == 'full':
        response['entry'] = entry
    return response

def _validate_route_terminal_memory_record(channel: str, record: Mapping[str, Any]) -> None:
    """Reject malformed control-shaped route reports before any file write."""
    if record.get('schema_version') != ROUTE_TERMINAL_REPORT_SCHEMA:
        return
    required = {'schema_version', 'thread_id', 'plan_id', 'status', 'report_text', 'report_sha256', 'remaining_obligations', 'decisive_stuck_points'}
    if set(record) != required:
        raise ValueError('route terminal report must use its exact released schema')
    if channel not in {'proof_steps', 'failed_paths'}:
        raise ValueError('route terminal channel must be proof_steps or failed_paths')
    thread_id = record.get('thread_id')
    if not isinstance(thread_id, str):
        raise ValueError('route terminal thread_id must be a string')
    normalized_thread_id = _normalize_route_terminal_thread_id(thread_id)
    if thread_id != normalized_thread_id:
        raise ValueError('route terminal thread_id must already use its normalized route-local form')
    plan_id = record.get('plan_id')
    if not isinstance(plan_id, str) or _GENERATION_CONTROL_EVIDENCE_ID_RE.fullmatch(plan_id) is None:
        raise ValueError('route terminal plan_id must match [A-Za-z0-9_.:-]{1,128}')
    if record.get('status') not in {'candidate', 'partial', 'blocked'}:
        raise ValueError('route terminal status must be candidate, partial, or blocked')
    report_text = record.get('report_text')
    if not isinstance(report_text, str):
        raise ValueError('route terminal report_text must be a string')
    if not report_text.strip():
        raise ValueError('route terminal report_text must be non-empty')
    if report_text != report_text.strip():
        raise ValueError('route terminal report_text must not have boundary whitespace')
    report_bytes = report_text.encode('utf-8')
    if len(report_bytes) > MAX_ROUTE_TERMINAL_REPORT_BYTES:
        raise ValueError(f'route terminal report_text exceeds the {MAX_ROUTE_TERMINAL_REPORT_BYTES}-byte limit')
    if not isinstance(record.get('report_sha256'), str) or record['report_sha256'] != hashlib.sha256(report_bytes).hexdigest():
        raise ValueError('route terminal report_sha256 does not match report_text')
    _round_text_list(record['remaining_obligations'], label='route terminal remaining obligations')
    _round_text_list(record['decisive_stuck_points'], label='route terminal decisive stuck points')

def _normalize_route_terminal_thread_id(thread_id: Any) -> str:
    """Normalize a direct native `/root/<route>` id for durable memory."""
    if not isinstance(thread_id, str):
        raise ValueError('route terminal thread_id must be a string')
    if thread_id.startswith(_NATIVE_ROOT_THREAD_PREFIX):
        if os.getenv('RETHLAS_RUNTIME_PROFILE') != 'legacy':
            raise ValueError('direct /root/<route-local-id> normalization is available only in the legacy runtime')
        thread_id = thread_id[len(_NATIVE_ROOT_THREAD_PREFIX):]
    if _GENERATION_CONTROL_EVIDENCE_ID_RE.fullmatch(thread_id) is None:
        raise ValueError('route terminal thread_id must be a route-local id or direct /root/<route-local-id> canonical id matching [A-Za-z0-9_.:-]{1,128}')
    return thread_id

def _memory_batch_input_preflight(problem_id: str, items: List[Dict[str, Any]], *, trusted_control_publication: bool) -> tuple[List[Dict[str, Any]], bytes]:
    """Validate and encode a batch without making any durable write."""
    try:
        if not isinstance(problem_id, str) or sanitize_problem_id(problem_id) != problem_id:
            raise ValueError('problem_id must already be the canonical normalized identifier')
        if not isinstance(items, list) or not items:
            raise ValueError('items must be a non-empty JSON array')
        if len(items) > MAX_MEMORY_BATCH_RECORDS:
            raise ValueError(f'items must contain at most {MAX_MEMORY_BATCH_RECORDS} records')
        allowed_keys = {'channel', 'record', 'active', 'supersedes'}
        normalized_items: List[Dict[str, Any]] = []
        for index, item in enumerate(items):
            if not isinstance(item, dict):
                raise ValueError(f'items[{index}] must be a JSON object')
            unknown_keys = set(item) - allowed_keys
            if unknown_keys:
                unknown = ', '.join(sorted((str(key) for key in unknown_keys)))
                raise ValueError(f'items[{index}] has unknown fields: {unknown}')
            channel = item.get('channel')
            record = item.get('record')
            active = item.get('active', True)
            if not isinstance(channel, str):
                raise ValueError(f'items[{index}].channel must be a string')
            _channel_path(problem_id, channel)
            if (channel in _CONTROL_ONLY_MEMORY_CHANNELS or _is_route_transition_projection(channel, record)) and (not trusted_control_publication):
                raise ValueError(f'{channel} is reserved for trusted control publication')
            if not isinstance(record, dict):
                raise ValueError(f'items[{index}].record must be a JSON object')
            _validate_route_terminal_memory_record(channel, record)
            if not isinstance(active, bool):
                raise ValueError(f'items[{index}].active must be a boolean')
            raw_supersedes = item.get('supersedes')
            supersedes = _validate_supersedes(raw_supersedes)
            if 'supersedes' in item and raw_supersedes != supersedes:
                raise ValueError(f'items[{index}].supersedes must already be trimmed, duplicate-free canonical record ids')
            normalized_items.append({'channel': channel, 'record': record, 'active': active, 'supersedes': supersedes})
        try:
            encoded = json.dumps(normalized_items, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
        except (TypeError, ValueError, UnicodeError) as exc:
            raise ValueError(f'items must be strict JSON data: {exc}') from exc
        if len(encoded) > MAX_MEMORY_BATCH_UTF8_BYTES:
            raise ValueError(f'encoded items exceed the {MAX_MEMORY_BATCH_UTF8_BYTES}-byte checkpoint limit')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise MemoryCheckpointPreflightError(str(exc), retry_allowed=True) from exc
    return (normalized_items, encoded)

def memory_append_batch(problem_id: str, items: List[Dict[str, Any]], *, _trusted_control_publication: bool=False, _trusted_publication_preflight: Callable[[], Mapping[str, Any] | None] | None=None) -> Dict[str, Any]:
    """Append one bounded, content-addressed local Legacy checkpoint."""
    if _trusted_control_publication or _trusted_publication_preflight is not None:
        raise ValueError('legacy MCP cannot publish host control memory')
    items = _materialize_bound_external_plan_checkpoint_items(problem_id, items)
    normalized_items, encoded = _memory_batch_input_preflight(problem_id, items, trusted_control_publication=_trusted_control_publication)
    sanitized_problem_id = sanitize_problem_id(problem_id)
    batch_id = _batch_id_for_items(sanitized_problem_id, encoded)
    checkpoint_path = _batch_checkpoint_dir(sanitized_problem_id) / f'{batch_id}.json'
    try:
        existing_checkpoint = _validate_memory_batch_checkpoint_data(sanitized_problem_id, checkpoint_path)
    except FileNotFoundError:
        existing_checkpoint = None
    if existing_checkpoint is not None:
        if _checkpoint_normalized_items(existing_checkpoint) != normalized_items:
            raise ValueError('content-addressed memory batch checkpoint collides with different items')
        existing_commit = _read_memory_batch_commit(existing_checkpoint, checkpoint_path, allow_missing=True)
        if existing_commit is not None:
            existing_checkpoint, existing_commit = _durably_revalidate_memory_batch_artifacts(sanitized_problem_id, checkpoint_path)
            committed = {**existing_checkpoint, 'committed_at_utc': existing_commit['committed_at_utc'], 'committed_at_monotonic': existing_commit['committed_at_monotonic'], 'commit_sha256': existing_commit['commit_sha256'], 'publication_receipt': None}
            return _memory_batch_receipt(sanitized_problem_id, checkpoint_path, committed)
    try:
        initial_cutoffs = None
        _require_memory_batch_publication_open(initial_cutoffs)
    except ValueError as exc:
        raise MemoryCheckpointPreflightError(str(exc), retry_allowed=False) from exc
    timestamp = _utc_now()
    entries: List[Dict[str, Any]] = []
    for index, item in enumerate(normalized_items):
        record_id = _batch_record_id(batch_id, index)
        entry = {'record_id': record_id, 'timestamp_utc': timestamp, 'channel': item['channel'], 'active': item['active'], 'supersedes': item['supersedes'], 'batch_id': batch_id, 'record': item['record']}
        entries.append(entry)
    event = {'record_id': _batch_event_id(batch_id), 'timestamp_utc': timestamp, 'event_type': 'memory_append_batch', 'batch_id': batch_id, 'active': True, 'supersedes': [], 'appended_records': [{'record_id': entry['record_id'], 'channel': entry['channel']} for entry in entries]}
    candidate = {'schema': MEMORY_BATCH_SCHEMA, 'batch_id': batch_id, 'timestamp_utc': timestamp, 'records': entries, 'event': event}
    candidate['checkpoint_sha256'] = _memory_batch_checkpoint_sha256(candidate)
    _publish_atomic_json_once(checkpoint_path, candidate, problem_id=sanitized_problem_id, expected_normalized_items=normalized_items)
    checkpoint = _validate_memory_batch_checkpoint_data(sanitized_problem_id, checkpoint_path)
    if _checkpoint_normalized_items(checkpoint) != normalized_items:
        raise ValueError('content-addressed memory batch checkpoint collides with different items')
    existing_commit = _read_memory_batch_commit(checkpoint, checkpoint_path, allow_missing=True)
    if existing_commit is None:
        _publish_memory_batch_commit_once(checkpoint_path, checkpoint, initial_cutoffs=initial_cutoffs, publication_preflight=_trusted_publication_preflight)
    checkpoint = _validate_memory_batch_checkpoint_data(sanitized_problem_id, checkpoint_path)
    commit = _read_memory_batch_commit(checkpoint, checkpoint_path, allow_missing=False)
    if commit is None:
        raise ValueError('memory batch commit marker disappeared')
    checkpoint, commit = _durably_revalidate_memory_batch_artifacts(sanitized_problem_id, checkpoint_path)
    committed = {**checkpoint, 'committed_at_utc': commit['committed_at_utc'], 'committed_at_monotonic': commit['committed_at_monotonic'], 'commit_sha256': commit['commit_sha256'], 'publication_receipt': None}
    return _memory_batch_receipt(sanitized_problem_id, checkpoint_path, committed)

def _memory_batch_receipt(problem_id: str, checkpoint_path: Path, committed: Mapping[str, Any]) -> Dict[str, Any]:
    """Return the exact local-commit receipt supported by Legacy mode."""
    if committed.get('publication_receipt') is not None:
        raise ValueError('legacy MCP rejects host publication receipts')
    receipts = [{'record_id': entry['record_id'], 'channel': entry['channel'], 'active': entry['active'], 'supersedes': entry['supersedes']} for entry in committed['records']]
    return {'schema_version': MEMORY_BATCH_LOCAL_COMMIT_RECEIPT_SCHEMA, 'status': 'ok', 'problem_id': problem_id, 'batch_id': committed['batch_id'], 'timestamp_utc': committed['timestamp_utc'], 'committed_at_utc': committed['committed_at_utc'], 'committed_at_monotonic': committed['committed_at_monotonic'], 'commit_sha256': committed['commit_sha256'], 'checkpoint_sha256': committed['checkpoint_sha256'], 'count': len(receipts), 'records': receipts, 'checkpoint_path': str(checkpoint_path)}

def append_route_terminal_report(problem_id: str, thread_id: str, plan_id: str, status: str, report_text: str, remaining_obligations: List[str], decisive_stuck_points: List[str]) -> Dict[str, Any]:
    """Build and durably append the exact released route-terminal schema.

    The model supplies mathematical content only.  The trusted runtime owns
    boundary-whitespace normalization, UTF-8 sizing, SHA-256 binding, channel
    selection, and the generic memory-batch wrapper.
    """
    try:
        normalized_thread_id = _normalize_route_terminal_thread_id(thread_id)
    except ValueError as exc:
        raise MemoryCheckpointPreflightError(str(exc), retry_allowed=True) from exc
    if not isinstance(report_text, str):
        raise MemoryCheckpointPreflightError('route terminal report_text must be a string', retry_allowed=True)
    normalized_report = report_text.strip()
    if not normalized_report:
        raise MemoryCheckpointPreflightError('route terminal report_text must be non-empty', retry_allowed=True)
    try:
        report_bytes = normalized_report.encode('utf-8')
    except UnicodeEncodeError as exc:
        raise MemoryCheckpointPreflightError('route terminal report_text must be valid UTF-8', retry_allowed=True) from exc
    if len(report_bytes) > MAX_ROUTE_TERMINAL_REPORT_BYTES:
        raise MemoryCheckpointPreflightError(f'route terminal report_text is {len(report_bytes)} UTF-8 bytes; compress the same report to at most {MAX_ROUTE_TERMINAL_REPORT_BYTES} bytes', retry_allowed=True)
    record = {'schema_version': ROUTE_TERMINAL_REPORT_SCHEMA, 'thread_id': normalized_thread_id, 'plan_id': plan_id, 'status': status, 'report_text': normalized_report, 'report_sha256': hashlib.sha256(report_bytes).hexdigest(), 'remaining_obligations': remaining_obligations, 'decisive_stuck_points': decisive_stuck_points}
    channel = 'failed_paths' if status == 'blocked' else 'proof_steps'
    return memory_append_batch(problem_id=problem_id, items=[{'channel': channel, 'record': record, 'active': True, 'supersedes': []}])

def memory_search(problem_id: str, query: str, channels: Optional[List[str]]=None, limit_per_channel: int=10, max_chars: int=DEFAULT_MEMORY_SEARCH_MAX_CHARS, include_inactive: bool=False, newest_first: bool=True) -> Dict[str, Any]:
    """Search active memory with bounded records and a bounded response envelope.

    ``complete`` is false whenever positive-scoring matches are omitted by either
    ``limit_per_channel`` or ``max_chars``. ``returned_chars`` counts compact JSON
    characters for the returned result objects, preserving the released interface.
    Independently, the complete indented JSON text emitted by MCP is capped at
    ``MAX_MEMORY_SEARCH_RESPONSE_UTF8_BYTES``; no stored item is partially cut.
    BM25 relevance is primary and recency only breaks exact or near ties.
    """
    if not isinstance(query, str) or not query.strip():
        raise ValueError('query must be non-empty')
    try:
        query_bytes = query.encode('utf-8')
    except UnicodeEncodeError as exc:
        raise ValueError('query must be valid UTF-8') from exc
    if len(query_bytes) > MAX_MEMORY_SEARCH_QUERY_UTF8_BYTES:
        raise ValueError('query exceeds MAX_MEMORY_SEARCH_QUERY_UTF8_BYTES')
    if not isinstance(limit_per_channel, int) or isinstance(limit_per_channel, bool) or limit_per_channel <= 0:
        raise ValueError('limit_per_channel must be > 0')
    if not isinstance(max_chars, int) or isinstance(max_chars, bool) or max_chars <= 0:
        raise ValueError('max_chars must be a positive integer')
    if not isinstance(include_inactive, bool):
        raise ValueError('include_inactive must be a boolean')
    if not isinstance(newest_first, bool):
        raise ValueError('newest_first must be a boolean')
    if channels is None:
        search_channels = [name for name in CHANNEL_FILES if name != 'events']
    else:
        if not isinstance(channels, list):
            raise ValueError('channels must be a JSON array')
        search_channels = []
        for channel in channels:
            if not isinstance(channel, str):
                raise ValueError('channels entries must be strings')
            _channel_path(problem_id, channel)
            if channel not in search_channels:
                search_channels.append(channel)
    entries_by_channel = _load_memory_entries(problem_id)
    ranked_by_channel: Dict[str, List[Dict[str, Any]]] = {}
    corpus_count = 0
    for channel in search_channels:
        channel_entries = [entry for entry in entries_by_channel[channel] if include_inactive or entry['effective_active']]
        corpus_count += len(channel_entries)
        documents = [json.dumps(entry['item'], ensure_ascii=False) for entry in channel_entries]
        tokenized_documents = [_tokenize_bm25(document) for document in documents]
        scores = _bm25_score_documents(query, tokenized_documents)
        candidates: List[Dict[str, Any]] = []
        for entry, score in zip(channel_entries, scores):
            if score <= 0:
                continue
            normalized_item = dict(entry['item'])
            normalized_item['record_id'] = entry['record_id']
            normalized_item['active'] = entry['effective_active']
            normalized_item['supersedes'] = entry['supersedes']
            if entry['declared_active'] != entry['effective_active']:
                normalized_item['declared_active'] = entry['declared_active']
            if entry['superseded_by']:
                normalized_item['superseded_by'] = entry['superseded_by']
            result = {'score': score, 'item': normalized_item}
            candidates.append({'key': (channel, entry['ordinal']), 'channel': channel, 'record_id': entry['record_id'], 'score': score, 'timestamp_rank': _timestamp_rank(entry['item']), 'global_ordinal': entry['global_ordinal'], 'result': result, 'chars': _compact_json_chars(result)})
        candidates.sort(key=lambda candidate: _candidate_rank(candidate, newest_first), reverse=True)
        ranked_by_channel[channel] = candidates
    budget_candidates: List[Dict[str, Any]] = []
    for channel in search_channels:
        budget_candidates.extend(ranked_by_channel[channel][:limit_per_channel])
    budget_candidates.sort(key=lambda candidate: _candidate_rank(candidate, newest_first), reverse=True)
    returned_keys = set()
    returned_chars = 0
    for candidate in budget_candidates:
        candidate_chars = candidate['chars']
        if returned_chars + candidate_chars > max_chars:
            continue
        returned_keys.add(candidate['key'])
        returned_chars += candidate_chars
    all_matches: List[Dict[str, Any]] = []
    for channel in search_channels:
        all_matches.extend(ranked_by_channel[channel])
    all_matches.sort(key=lambda candidate: _candidate_rank(candidate, newest_first), reverse=True)
    sanitized_problem_id = sanitize_problem_id(problem_id)

    def build_response(selected_keys: set[tuple[str, int]], *, omitted_id_limit: int, response_limited: bool) -> Dict[str, Any]:
        results_by_channel: Dict[str, Dict[str, Any]] = {}
        selected_chars = 0
        for channel in search_channels:
            ranked = ranked_by_channel[channel]
            returned = [candidate for candidate in ranked if candidate['key'] in selected_keys]
            omitted = [candidate for candidate in ranked if candidate['key'] not in selected_keys]
            channel_returned_chars = sum((candidate['chars'] for candidate in returned))
            selected_chars += channel_returned_chars
            results_by_channel[channel] = {'corpus_count': sum((1 for entry in entries_by_channel[channel] if include_inactive or entry['effective_active'])), 'matched_count': len(ranked), 'count': len(returned), 'complete': not omitted, 'truncated': bool(omitted), 'omitted_count': len(omitted), 'omitted_ids': [candidate['record_id'] for candidate in omitted[:omitted_id_limit]], 'omitted_ids_complete': len(omitted) <= omitted_id_limit, 'returned_chars': channel_returned_chars, 'results': [candidate['result'] for candidate in returned]}
        omitted_matches = [candidate for candidate in all_matches if candidate['key'] not in selected_keys]
        return {'problem_id': sanitized_problem_id, 'query': query, 'channels': search_channels, 'limit_per_channel': limit_per_channel, 'max_chars': max_chars, 'response_max_utf8_bytes': MAX_MEMORY_SEARCH_RESPONSE_UTF8_BYTES, 'response_limited': response_limited, 'include_inactive': include_inactive, 'newest_first': newest_first, 'corpus_count': corpus_count, 'matched_count': len(all_matches), 'count': len(selected_keys), 'complete': not omitted_matches, 'truncated': bool(omitted_matches), 'omitted_count': len(omitted_matches), 'omitted_ids': [candidate['record_id'] for candidate in omitted_matches[:omitted_id_limit]], 'omitted_ids_complete': len(omitted_matches) <= omitted_id_limit, 'returned_chars': selected_chars, 'results_by_channel': results_by_channel}
    response = build_response(returned_keys, omitted_id_limit=MAX_OMITTED_IDS, response_limited=False)
    if _memory_search_response_utf8_bytes(response) <= MAX_MEMORY_SEARCH_RESPONSE_UTF8_BYTES:
        return response
    initially_returned = [candidate for candidate in all_matches if candidate['key'] in returned_keys]

    def response_for_prefix(count: int, *, omitted_id_limit: int) -> Dict[str, Any]:
        selected = {candidate['key'] for candidate in initially_returned[:count]}
        return build_response(selected, omitted_id_limit=omitted_id_limit, response_limited=True)
    low = 0
    high = len(initially_returned)
    while low < high:
        middle = (low + high + 1) // 2
        candidate_response = response_for_prefix(middle, omitted_id_limit=0)
        if _memory_search_response_utf8_bytes(candidate_response) <= MAX_MEMORY_SEARCH_RESPONSE_UTF8_BYTES:
            low = middle
        else:
            high = middle - 1
    retained_count = low
    omitted_low = 0
    omitted_high = MAX_OMITTED_IDS
    while omitted_low < omitted_high:
        middle = (omitted_low + omitted_high + 1) // 2
        candidate_response = response_for_prefix(retained_count, omitted_id_limit=middle)
        if _memory_search_response_utf8_bytes(candidate_response) <= MAX_MEMORY_SEARCH_RESPONSE_UTF8_BYTES:
            omitted_low = middle
        else:
            omitted_high = middle - 1
    response = response_for_prefix(retained_count, omitted_id_limit=omitted_low)
    if _memory_search_response_utf8_bytes(response) > MAX_MEMORY_SEARCH_RESPONSE_UTF8_BYTES:
        raise ValueError('memory_search response metadata exceeds its hard limit')
    return response

def branch_update(problem_id: str, branch_id: str, state: Dict[str, Any]) -> Dict[str, Any]:
    payload = {'branch_id': branch_id, 'state': state}
    return memory_append(problem_id, 'branch_states', payload)

def _validate_generation_control_instance(instance_id: str) -> str:
    if not isinstance(instance_id, str) or _GENERATION_CONTROL_INSTANCE_RE.fullmatch(instance_id) is None:
        raise ValueError('generation control instance id must be 32 lowercase hex')
    return instance_id

def _generation_control_root() -> Path:
    root = GENERATION_CONTROL_ROOT.absolute()
    try:
        root.mkdir(mode=448)
    except FileExistsError:
        pass
    metadata = root.lstat()
    if not stat.S_ISDIR(metadata.st_mode) or root.is_symlink() or stat.S_IMODE(metadata.st_mode) != 448 or (hasattr(os, 'getuid') and metadata.st_uid != os.getuid()):
        raise ValueError('generation control root must be a real owner-only directory')
    return root

def _generation_control_path(problem_id: str, instance_id: str) -> Path:
    sanitized_problem_id = validate_verified_problem_id(problem_id)
    normalized_instance = _validate_generation_control_instance(instance_id)
    problem_digest = hashlib.sha256(sanitized_problem_id.encode('utf-8')).hexdigest()
    return _generation_control_root() / f'{normalized_instance}_{problem_digest}.json'

def _replace_generation_control(path: Path, payload: Dict[str, Any]) -> None:
    """Atomically replace one deterministic current-state control record.

    Unlike immutable phase checkpoints, this file intentionally represents the
    latest owner-resume or generation-yield state.  Retrying after an ambiguous
    directory fsync writes the same desired payload and is therefore safe.
    """
    encoded = (json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode('utf-8')
    if len(encoded) > MAX_GENERATION_CONTROL_FILE_BYTES:
        raise ValueError('generation control record exceeds its file-size limit')
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.parent / f'.{path.name}.{uuid.uuid4().hex}.tmp'
    descriptor: int | None = None
    try:
        descriptor = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 384)
        with os.fdopen(descriptor, 'wb') as handle:
            descriptor = None
            handle.write(encoded)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        directory_descriptor = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory_descriptor)
        finally:
            os.close(directory_descriptor)
    finally:
        if descriptor is not None:
            os.close(descriptor)
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass

def _validate_generation_control_reason(reason: str) -> str:
    if not isinstance(reason, str) or not reason or reason != reason.strip() or ('\x00' in reason) or (len(reason.encode('utf-8')) > MAX_GENERATION_CONTROL_REASON_BYTES):
        raise ValueError(f'generation control reason must be a trimmed non-empty UTF-8 string of at most {MAX_GENERATION_CONTROL_REASON_BYTES} bytes')
    return reason

def _round_text_list(value: Any, *, label: str, maximum_items: int=16) -> List[str]:
    if not isinstance(value, list) or not 1 <= len(value) <= maximum_items or any((not isinstance(item, str) or not item.strip() or item != item.strip() or ('\x00' in item) or (len(item.encode('utf-8')) > 2048) for item in value)) or (len(set(value)) != len(value)):
        raise ValueError(f'{label} must be a bounded unique text list')
    return list(value)

def _generation_control_payload(problem_id: str, *, instance_id: str, state: str, reason: str, evidence_record_ids: List[str]) -> Dict[str, Any]:
    sanitized_problem_id = validate_verified_problem_id(problem_id)
    _statement, statement_digest = _trusted_problem_statement(sanitized_problem_id)
    normalized_instance = _validate_generation_control_instance(instance_id)
    normalized_reason = _validate_generation_control_reason(reason)
    if state == 'running':
        if evidence_record_ids:
            raise ValueError('running generation control cannot cite wait evidence')
        normalized_evidence: List[str] = []
    else:
        raise ValueError('legacy generation control forbids owner-wait states')
    return {'schema': GENERATION_CONTROL_SCHEMA, 'instance_id': normalized_instance, 'problem_id': sanitized_problem_id, 'statement_sha256': statement_digest, 'state': state, 'reason': normalized_reason, 'evidence_record_ids': normalized_evidence}

def _set_generation_control(problem_id: str, *, instance_id: str, state: str, reason: str, evidence_record_ids: List[str]) -> Dict[str, Any]:
    payload = _generation_control_payload(problem_id, instance_id=instance_id, state=state, reason=reason, evidence_record_ids=evidence_record_ids)
    _replace_generation_control(_generation_control_path(payload['problem_id'], payload['instance_id']), payload)
    return dict(payload)

def generation_control_resume(problem_id: str, instance_id: str) -> Dict[str, Any]:
    """Record the repository owner's explicit runner invocation as a resume."""
    return _set_generation_control(problem_id, instance_id=instance_id, state='running', reason='owner_runner_started', evidence_record_ids=[])

def generation_control_status(problem_id: str, instance_id: str, *, owner_manifest_snapshot_json: str | None=None) -> Dict[str, Any]:
    if owner_manifest_snapshot_json is not None:
        raise ValueError('legacy MCP rejects owner publication snapshots')
    sanitized_problem_id = validate_verified_problem_id(problem_id)
    normalized_instance = _validate_generation_control_instance(instance_id)
    _statement, statement_digest = _trusted_problem_statement(sanitized_problem_id)
    path = _generation_control_path(sanitized_problem_id, normalized_instance)
    try:
        metadata = path.lstat()
    except FileNotFoundError:
        return {'schema': GENERATION_CONTROL_SCHEMA, 'instance_id': normalized_instance, 'problem_id': sanitized_problem_id, 'statement_sha256': statement_digest, 'state': 'running', 'reason': 'no_generation_control_record', 'evidence_record_ids': []}
    if not stat.S_ISREG(metadata.st_mode) or path.is_symlink() or metadata.st_nlink != 1 or (stat.S_IMODE(metadata.st_mode) != 384) or (hasattr(os, 'getuid') and metadata.st_uid != os.getuid()) or (metadata.st_size <= 0) or (metadata.st_size > MAX_GENERATION_CONTROL_FILE_BYTES):
        raise ValueError('generation control record is not a safe bounded file')
    descriptor = os.open(path, os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0))
    try:
        opened = os.fstat(descriptor)
        if not stat.S_ISREG(opened.st_mode) or opened.st_nlink != 1 or stat.S_IMODE(opened.st_mode) != 384 or (hasattr(os, 'getuid') and opened.st_uid != os.getuid()) or (opened.st_size <= 0) or (opened.st_size > MAX_GENERATION_CONTROL_FILE_BYTES):
            raise ValueError('generation control record changed during open')
        raw_bytes = os.read(descriptor, MAX_GENERATION_CONTROL_FILE_BYTES + 1)
    finally:
        os.close(descriptor)
    if len(raw_bytes) > MAX_GENERATION_CONTROL_FILE_BYTES:
        raise ValueError('generation control record exceeds its file-size limit')
    try:
        raw = raw_bytes.decode('utf-8')
    except UnicodeDecodeError as exc:
        raise ValueError('generation control record is not UTF-8') from exc
    payload = _strict_json_loads(raw, label='generation control record')
    if not isinstance(payload, dict) or set(payload) != {'schema', 'instance_id', 'problem_id', 'statement_sha256', 'state', 'reason', 'evidence_record_ids'}:
        raise ValueError('generation control record has an invalid envelope')
    if payload.get('schema') != GENERATION_CONTROL_SCHEMA or payload.get('instance_id') != normalized_instance or payload.get('problem_id') != sanitized_problem_id or (payload.get('statement_sha256') != statement_digest):
        raise ValueError('generation control record has invalid bindings')
    state = payload.get('state')
    reason = payload.get('reason')
    evidence = payload.get('evidence_record_ids')
    _validate_generation_control_reason(reason)
    if state == 'running':
        if evidence != []:
            raise ValueError('running generation control has invalid evidence')
    else:
        raise ValueError('legacy generation control forbids owner-wait states')
    return dict(payload)

def generation_control_receipt(problem_id: str, instance_id: str, *, owner_manifest_snapshot_json: str | None=None) -> Dict[str, Any]:
    """Content-bind one trusted control projection for host cadence admission."""
    control = generation_control_status(problem_id, instance_id, owner_manifest_snapshot_json=owner_manifest_snapshot_json)
    return {'schema_version': 'rethlas_generation_control_receipt_v1', 'control': control, 'record_sha256': hashlib.sha256(canonical_json_bytes(control)).hexdigest()}

def _exact_checkpoint_tool_result(receipt: Dict[str, Any]) -> Any:
    """Return one cross-SDK-stable CallToolResult for durable checkpoints."""
    if CallToolResult is None or TextContent is None:
        raise RuntimeError('the official MCP SDK result types are unavailable')
    encoded = json.dumps(receipt, allow_nan=False, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
    return CallToolResult(content=[TextContent(type='text', text=encoded)], structuredContent=receipt, isError=False)

def _checkpoint_failure_tool_result(exc: MemoryCheckpointPreflightError) -> Any:
    """Expose a bounded checkpoint validation error instead of an SDK placeholder."""
    if CallToolResult is None or TextContent is None:
        raise RuntimeError('the official MCP SDK result types are unavailable')
    detail = str(exc).strip() or 'memory checkpoint validation failed'
    payload = {'schema_version': MEMORY_CHECKPOINT_FAILURE_SCHEMA, 'status': 'preflight_failed', 'category': 'memory_checkpoint_validation', 'error': detail, 'retry_allowed': exc.retry_allowed, 'checkpoint_committed': False}
    encoded = json.dumps(payload, allow_nan=False, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
    return CallToolResult(content=[TextContent(type='text', text=encoded)], structuredContent=payload, isError=True)
LEGACY_FRONTIER_SCHEMA = "rethlas_legacy_frontier_receipt_v1"
MAX_LEGACY_FRONTIER_BLUEPRINT_BYTES = 8_000_000


def _legacy_blueprint_commitment(problem_id: str) -> Optional[Dict[str, Any]]:
    results_root = Path(os.path.abspath(os.fspath(RESULTS_ROOT)))
    candidate = results_root.joinpath(*problem_id.split("/"), "blueprint.md")
    try:
        metadata = candidate.lstat()
    except FileNotFoundError:
        return None
    if (
        candidate.is_symlink()
        or not stat.S_ISREG(metadata.st_mode)
        or metadata.st_nlink != 1
        or metadata.st_size < 1
        or metadata.st_size > MAX_LEGACY_FRONTIER_BLUEPRINT_BYTES
    ):
        raise ValueError("legacy frontier blueprint is not a bounded regular file")
    resolved_results = results_root.resolve(strict=True)
    resolved_candidate = candidate.resolve(strict=True)
    if (
        not resolved_candidate.is_relative_to(resolved_results)
        or resolved_candidate != candidate.absolute()
    ):
        raise ValueError("legacy frontier blueprint escaped the results root")
    descriptor = os.open(
        candidate,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        opened = os.fstat(descriptor)
        identity = (
            opened.st_dev,
            opened.st_ino,
            opened.st_size,
            opened.st_mtime_ns,
        )
        if identity != (
            metadata.st_dev,
            metadata.st_ino,
            metadata.st_size,
            metadata.st_mtime_ns,
        ):
            raise ValueError("legacy frontier blueprint changed during open")
        remaining = int(opened.st_size)
        chunks: List[bytes] = []
        while remaining:
            chunk = os.read(descriptor, min(65_536, remaining))
            if not chunk:
                raise ValueError("legacy frontier blueprint produced a short read")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise ValueError("legacy frontier blueprint grew during read")
        after = os.fstat(descriptor)
        if identity != (
            after.st_dev,
            after.st_ino,
            after.st_size,
            after.st_mtime_ns,
        ):
            raise ValueError("legacy frontier blueprint changed during read")
    finally:
        os.close(descriptor)
    raw = b"".join(chunks)
    return {
        "sha256": hashlib.sha256(raw).hexdigest(),
        "bytes": len(raw),
    }


def _legacy_frontier_receipt(
    problem_id: str, *, excluded_record_ids: frozenset[str]
) -> Dict[str, Any]:
    normalized_problem_id = validate_verified_problem_id(problem_id)
    _statement, statement_sha256 = _trusted_problem_statement(normalized_problem_id)
    entries_by_channel = _load_memory_entries(normalized_problem_id)
    memory_records = []
    found_exclusions: set[str] = set()
    for channel in CHANNEL_FILES:
        for entry in entries_by_channel[channel]:
            record_id = str(entry["record_id"])
            if record_id in excluded_record_ids:
                found_exclusions.add(record_id)
                continue
            memory_records.append(
                {
                    "channel": channel,
                    "record_id": record_id,
                    "effective_active": bool(entry["effective_active"]),
                    "item_sha256": hashlib.sha256(
                        canonical_json_bytes(entry["item"])
                    ).hexdigest(),
                }
            )
    if found_exclusions != set(excluded_record_ids):
        raise ValueError("legacy frontier exclusion does not name exact records")
    memory_sha256 = hashlib.sha256(
        canonical_json_bytes(memory_records)
    ).hexdigest()
    body = {
        "schema_version": LEGACY_FRONTIER_SCHEMA,
        "problem_id": normalized_problem_id,
        "statement_sha256": statement_sha256,
        "blueprint": _legacy_blueprint_commitment(normalized_problem_id),
        "memory_sha256": memory_sha256,
        "memory_record_count": len(memory_records),
    }
    return {
        **body,
        "frontier_sha256": hashlib.sha256(canonical_json_bytes(body)).hexdigest(),
    }


def legacy_frontier_receipt(problem_id: str) -> Dict[str, Any]:
    return _legacy_frontier_receipt(problem_id, excluded_record_ids=frozenset())


def legacy_frontier_receipt_without_records(
    problem_id: str, record_ids: List[str]
) -> Dict[str, Any]:
    """Reconstruct a prior frontier after excluding one exact trusted batch.

    This helper is host-only recovery evidence.  It never mutates memory and
    rejects duplicate, malformed, missing, or non-content-addressed ids.
    """

    if (
        not isinstance(record_ids, list)
        or not 1 <= len(record_ids) <= MAX_MEMORY_BATCH_RECORDS
        or any(
            not isinstance(record_id, str)
            or re.fullmatch(r"(?:mem|event)_[0-9a-f]{64}", record_id) is None
            for record_id in record_ids
        )
        or len(set(record_ids)) != len(record_ids)
    ):
        raise ValueError("legacy frontier exclusions must be unique record ids")
    return _legacy_frontier_receipt(
        problem_id, excluded_record_ids=frozenset(record_ids)
    )


LEGACY_TOOL_NAMES = frozenset(
    {
        "search_matlas_theorems",
        "search_arxiv_theorems",
        "read_arxiv_primary",
        "append_route_terminal_report",
        "verify_blueprint_service",
        "memory_init",
        "memory_append",
        "memory_append_batch",
        "memory_search",
        "branch_update",
    }
)


def build_mcp_app() -> Optional[Any]:
    if FastMCP is None:
        return None
    app = FastMCP("reasoning-agent")

    def register(name: str):
        if name not in LEGACY_TOOL_NAMES:
            raise AssertionError("legacy MCP registration escaped its allowlist")

        def decorator(function: Any) -> Any:
            return app.tool(name=name)(function)

        return decorator

    @register("search_matlas_theorems")
    def tool_search_matlas_theorems(
        query: str, num_results: int = 10
    ) -> Dict[str, Any]:
        return search_matlas_theorems(query=query, num_results=num_results)

    @register("search_arxiv_theorems")
    def tool_search_arxiv_theorems(
        problem_id: str, query: str, num_results: int = 10
    ) -> Dict[str, Any]:
        return search_arxiv_theorems_for_problem(
            problem_id=problem_id,
            query=query,
            num_results=num_results,
        )

    @register("read_arxiv_primary")
    def tool_read_arxiv_primary(
        problem_id: str,
        arxiv_id: str,
        locator: str,
        max_excerpt_bytes: int = 20_000,
    ) -> Dict[str, Any]:
        return read_arxiv_primary_for_problem(
            problem_id=problem_id,
            arxiv_id=arxiv_id,
            locator=locator,
            max_excerpt_bytes=max_excerpt_bytes,
        )

    @register("append_route_terminal_report")
    def tool_append_route_terminal_report(
        problem_id: str,
        thread_id: str,
        plan_id: str,
        status: str,
        report_text: str,
        remaining_obligations: List[str],
        decisive_stuck_points: List[str],
    ) -> Any:
        try:
            receipt = append_route_terminal_report(
                problem_id=problem_id,
                thread_id=thread_id,
                plan_id=plan_id,
                status=status,
                report_text=report_text,
                remaining_obligations=remaining_obligations,
                decisive_stuck_points=decisive_stuck_points,
            )
        except MemoryCheckpointPreflightError as exc:
            return _checkpoint_failure_tool_result(exc)
        return _exact_checkpoint_tool_result(receipt)

    @register("verify_blueprint_service")
    def tool_verify_blueprint_service(problem_id: str) -> Dict[str, Any]:
        return verify_blueprint_service(problem_id=problem_id)

    @register("memory_init")
    def tool_memory_init(
        problem_id: str, meta: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        return memory_init(problem_id=problem_id, meta=meta)

    @register("memory_append")
    def tool_memory_append(
        problem_id: str,
        channel: str,
        record: Dict[str, Any],
        active: bool = True,
        supersedes: Optional[List[str]] = None,
        return_mode: str = "metadata",
    ) -> Dict[str, Any]:
        return memory_append(
            problem_id=problem_id,
            channel=channel,
            record=record,
            active=active,
            supersedes=supersedes,
            return_mode=return_mode,
        )

    @register("memory_append_batch")
    def tool_memory_append_batch(
        problem_id: str, items: List[Dict[str, Any]]
    ) -> Any:
        try:
            receipt = memory_append_batch(problem_id=problem_id, items=items)
        except MemoryCheckpointPreflightError as exc:
            return _checkpoint_failure_tool_result(exc)
        return _exact_checkpoint_tool_result(receipt)

    @register("memory_search")
    def tool_memory_search(
        problem_id: str,
        query: str,
        channels: Optional[List[str]] = None,
        limit_per_channel: int = 10,
        max_chars: int = DEFAULT_MEMORY_SEARCH_MAX_CHARS,
        include_inactive: bool = False,
        newest_first: bool = True,
    ) -> Dict[str, Any]:
        return memory_search(
            problem_id=problem_id,
            query=query,
            channels=channels,
            limit_per_channel=limit_per_channel,
            max_chars=max_chars,
            include_inactive=include_inactive,
            newest_first=newest_first,
        )

    @register("branch_update")
    def tool_branch_update(
        problem_id: str, branch_id: str, state: Dict[str, Any]
    ) -> Dict[str, Any]:
        return branch_update(problem_id=problem_id, branch_id=branch_id, state=state)

    return app


APP = build_mcp_app()


def main() -> None:
    control_token = os.environ.get("RETHLAS_GENERATION_CONTROL_TOKEN", "")
    if len(sys.argv) == 3 and sys.argv[1] == "--legacy-frontier-receipt":
        receipt = legacy_frontier_receipt(sys.argv[2])
        print(canonical_json_bytes(receipt).decode("utf-8"))
        return
    if len(sys.argv) == 3 and sys.argv[1] == "--generation-control-state":
        print(generation_control_status(sys.argv[2], control_token)["state"])
        return
    if len(sys.argv) == 3 and sys.argv[1] == "--generation-control-resume":
        generation_control_resume(sys.argv[2], control_token)
        return
    if len(sys.argv) == 3 and sys.argv[1] == "--generation-control-receipt":
        receipt = generation_control_receipt(sys.argv[2], control_token)
        print(canonical_json_bytes(receipt).decode("utf-8"))
        return
    if APP is None:
        raise SystemExit(
            "the official MCP SDK is missing or incompatible. Install "
            "requirements from mcp/requirements.txt first."
        )
    APP.run()


if __name__ == "__main__":
    main()
